window.DGNL_DE_MON["l17"] = {"id": "l17", "ten": "Đề thi thử số 17", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "<i>Ngày xưa, có một bác lực điền tên </i>là<i> Ba ở trong một xóm dưới chân núi. Bác không có ruộng phải làm rẽ năm sào của một phú ông ở làng bên cạnh. Phú ông là tay giàu có nhất tổng, ruộng đất trâu bò ở rải rác các thôn xóm nhiều lúc không đếm xiết. Thấy bác là tá điền cũ, tính nết thật thà chăm chỉ, lúc nào cũng nộp thóc sòng phẳng, phú ông có lòng tin giao cho bác nuôi trâu. Từ đấy công việc của bác Ba thêm bận rộn. Ngày ngày bác phải chăn một bầy trâu của phú ông từ độ ấy đến giờ sinh nở tổng cộng đã được năm con. </i><br>Đoạn trích trên thuộc thể loại nào?", "choices": ["Truyện cổ tích", "Truyền thuyết", "Sử thi", "Thần thoại."], "correctIndex": 0, "explain": "<b>Câu 1 chọn A</b> Giải thích: Câu chuyện kể về bác Ba là một người nông dân nghèo làm thuê (lực điền, làm rẽ) và một phú ông giàu có , đây là môtíp nhân vật và hoàn cảnh rất đặc trưng của thể loại truyện cổ tích sinh hoạt."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><b>_______:</b><br>(Cầm vàng hát sắp) - Ở hiền rồi lại gặp lành<br>Mẹ lại ngại thân con (Hát văn)<br>Như dao cắt ruột mẹ ra (Nói)<br>- Con ơi, trời còn sớm hay đã tối mà con cứ dắt mẹ đi mãi thế này?<br>Gặp vợ chú quỷ cho thanh tre già<br>(Nói sử) Ối con ơi,<br>Mẹ cảm thương thân mẹ<br>Trăm sầu, nghìn thảm chất đà nên con!<br><b>Thị Phương:</b><br>- Trình lạy mẹ<br>Vầng ô đã lặn<br>Vắng vẻ của nhà<br>Mẹ con ta vào gốc cây đa<br>Nằm nghỉ tạm qua đêm sẽ liệu (ngồi nghỉ)<br>(Trích chèo “Trương Viên)<br>Vị trí trống là tên một loại vai diễn trong chèo. Từ phù hợp điền vào ô trống là từ nào?", "choices": ["Mụ", "Lão", "Hề", "Đào thương."], "correctIndex": 0, "explain": "<b>Câu 2 chọn A</b> Giải thích: Nhân vật trong đoạn trích xưng &quot;mẹ&quot; và gọi &quot;con&quot; (Thị Phương xưng là con, gọi mẹ chồng). Trong nghệ thuật chèo truyền thống, vai diễn người phụ nữ lớn tuổi (như mẹ chồng) được gọi là vai Mụ (đào mụ)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><table class=\"bang-de\"><tr><td><b>Bản gốc</b></td><td><b>Bản dịch</b></td></tr><tr><td>“Nhị thánh hề tịnh minh,<br>Tựu thử giang hề tẩy giáp binh.<br>Hồ trần bất cảm động hề, thiên cổ thăng bình.<br>Tín tri: bất tại quan hà chi hiểm hề,<br>Duy tại ý đức chi mạc kinh.”<br>(Bạch Đằng giang phú, Trương Hán Siêu)</td><td>“Anh minh hai vị thánh quân,<br>Sông đây rửa sạch mấy lần giáp binh.<br>Giặc tan muôn thuở thanh bình,<br>Bởi đâu đất hiểm, cốt mình đức cao.”<br>(Phú sông Bạch Đằng, Trương Hán Siêu)</td></tr></table><br>Đoạn thơ trên thể hiện nổi bật nhất đặc trưng nào của văn học trung đại?", "choices": ["Tính sùng cổ", "Tính ước lệ tượng trưng", "Tính quy phạm", "Tính cộng đồng."], "correctIndex": 0, "explain": "<b>Câu 3 chọn A</b> Giải thích: Đoạn trích đề cao &quot;ý đức&quot; (cốt mình đức cao) của các bậc thánh quân đời trước để giữ nền hòa bình. Việc hướng về và ca ngợi những giá trị đạo đức tốt đẹp, truyền thống của người xưa mang đậm tính sùng cổ của văn học trung đại"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><table class=\"bang-de\"><tr><td><b><i>Ai tư vãn (Ngọc Hân công chúa)</i></b></td><td><b><i>Chinh phụ ngâm (Đặng Trần Côn, bản diễn Nôm của Phan Huy Ích)</i></b></td></tr><tr><td>Buồn xem hoa, hoa buồn thêm thẹn,<br>Cánh hải đường đã quyện giọt sương.<br>Trông chim càng dễ đoạn trường:<br>Uyên ương chiếc bóng, phượng hoàng lẻ đôi.<br>Cảnh nào cũng ngùi ngùi cảnh ấy,<br>Tiệc vui mừng còn thấy chi đâu?<br>Phút giây bãi bể nương dâu,<br>Cuộc đời là thế, biết hầu nài sao?</td><td>Kìa loài sâu đôi đầu cùng cánh<br>Nọ loài chim chắp cánh cùng bay<br>Liễu sen là thức cỏ cây<br>Ðôi hoa cũng dính, đôi dây cũng liền<br>Ấy loài vật tình duyên còn thế<br>Sao kiếp người nỡ để đấy đây?<br>Thiếp xin về kiếp sau này<br>Như chim liền cánh, như cây liền cành.</td></tr></table><br>Đâu là điểm tương đồng giữa hai đoạn trích trên?", "choices": ["Đều mượn hình ảnh sự vật trong tự nhiên để soi chiếu nỗi cô đơn, chia lìa của con người.", "Đều mượn hình ảnh đôi lứa trong tự nhiên để khẳng định khát vọng hạnh phúc lứa đôi mang màu sắc nhân đạo.", "Đều thể hiện tiếng nói phản kháng trực diện đối với xã hội phong kiến đã tước đoạt hạnh phúc cá nhân.", "Đều mượn hình ảnh chia lìa trong tự nhiên để phản ánh sự đứt gãy các mối quan hệ trong chiến tranh."], "correctIndex": 0, "explain": "<b>Câu 4 chọn A</b> Giải thích: Cả hai đoạn thơ đều sử dụng hình ảnh các sinh vật có đôi có cặp trong tự nhiên (uyên ương, phượng hoàng, chim chắp cánh, liễu sen) để làm nổi bật và soi chiếu nỗi đau đớn, cô đơn, lẻ loi của con người."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“<i>Cái khổ làm héo một phần lớn những tính tình tươi đẹp của người ta. Tiếng đau khổ vang dội lên mạnh mẽ. Chao ôi! Chao ôi! Nghệ thuật không cần là ánh trăng lừa dối, nghệ thuật có thể chỉ là tiếng đau khổ kia, thoát ra từ những kiếp lầm than, vang dội lên mạnh mẽ trong lòng Ðiền.” </i>(Giăng sáng, Nam Cao)<br>Đoạn trích trên thể hiện rõ đặc trưng của trường phái sáng tác nào?", "choices": ["Chủ nghĩa hiện thực", "Chủ nghĩa lãng mạn", "Chủ nghĩa tượng trưng", "Chủ nghĩa siêu thực."], "correctIndex": 0, "explain": "<b>Câu 5 chọn A</b> Giải thích: Quan điểm &quot;Nghệ thuật không cần là ánh trăng lừa dối&quot; mà phải là &quot;tiếng đau khổ kia, thoát ra từ những kiếp lầm than&quot; chính là tuyên ngôn nghệ thuật tiêu biểu của chủ nghĩa hiện thực, đòi hỏi văn học phải bám sát và phản ánh chân thật đời sống"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>HỒN MA: Con hãy sẵn sàng trả thù cho ta, khi nghe xong lời ta nói.<br>HAM-LÉT: Sao?<br>HỒN MA: Ta là hồn cha con, còn bị đoạ đày trong ít lâu nữa, đêm đêm phải đi lang thang, ngày ngày bị bỏ đói, giam mình trong lửa, cho đến khi lửa kia thiêu sạch hết những tội ác nhơ bẩn đã phạm phải khi còn sống trên cõi trần. Phải chi ta không bị cấm tiết lộ những điều bí ẩn nơi địa ngục giam cầm ta, thì ta sẽ kể cho con nghe một câu chuyện dị kì mà mỗi tiếng sẽ vò xé tan nát tâm hồn con, làm cho bầu máu đỏ nóng thanh xuân phải đông giá, làm cho hai mắt con bật ra khỏi tròng như hai ngôi sao lạc khỏi vòng quỹ đạo, mái tóc kết chặt của con sẽ rã rời tơi tả, tóc gáy con sẽ dựng đứng lên như lông dím lúc sợ hãi. Nhưng những điều bí mật ở cõi vô cùng vô tận kia không thể kể cho người trần mắt thịt nghe được. Hãy nghe ta, hãy nghe ta, ôi hãy nghe ta nếu con vẫn thương yêu người cha thiết cốt của con.<br>(Trích Hamlet, William Shakespeare)<br>Đâu là nhận định đúng nhất về nội dung của đoạn trích trên?", "choices": ["Đoạn trích cho thấy hồn ma người cha thúc giục Ham-lét lắng nghe một bí mật kinh hoàng, từ đó chuẩn bị cho nhiệm vụ trả thù.", "Đoạn trích tập trung làm nổi bật nỗi đau đớn và sự đọa đày của hồn ma, qua đó khơi dậy lòng thương xót nơi Ham-lét hơn là trực tiếp dẫn đến hành động.", "Đoạn trích cho thấy hồn ma dùng những hình ảnh ghê rợn về cõi chết để tạo áp lực tinh thần, khiến Ham-lét bị cuốn vào một bổn phận vượt quá khả năng lựa chọn.", "Đoạn trích nhấn mạnh sự bí ẩn của thế giới bên kia, qua đó đặt Ham-lét trước một sự thật vừa bị che giấu vừa có sức làm đảo lộn nhận thức con người."], "correctIndex": 0, "explain": "<b>Câu 6 chọn A</b> Giải thích: Hồn ma hiện về không chỉ kể lại sự thống khổ dưới địa ngục mà mục đích chính là để khơi dậy sự phẫn nộ, yêu cầu Ham-lét lắng nghe sự thật để &quot;sẵn sàng trả thù&quot; cho cái chết của cha."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><table class=\"bang-de\"><tr><td><b>Ngữ liệu 1</b></td><td><b>Ngữ liệu 2</b></td></tr><tr><td>“Gần xa đâu đây<br>Nghe tiếng thác chảy<br>Lá non tràn đầy”<i>(Bu-son)</i></td><td>“Nắng rọi Hương Lô khói tía bay<br>Xa trông dòng thác nước sông này.<br>Nước bay thẳng xuống ba nghìn thước,<br>Tưởng dải ngân hà tuột khỏi mây.”<i>(Lý Bạch)</i></td></tr></table><br>Đâu không phải là điểm khác biệt trong cách cảm nhận thiên nhiên của hai ngữ liệu trên?", "choices": ["Ngữ liệu 1 gợi thiên nhiên qua âm thanh gần xa và sắc xanh non; ngữ liệu 2 dựng thiên nhiên bằng ánh sáng, độ cao và chuyển động mạnh.", "Ngữ liệu 1 cảm nhận thiên nhiên bằng ấn tượng thoáng nhẹ, hàm súc; ngữ liệu 2 cảm nhận thiên nhiên bằng cái nhìn rộng mở, kì vĩ.", "Ngữ liệu 1 nghiêng về khoảnh khắc nhỏ, ít lời mà nhiều dư vang; ngữ liệu 2 nghiêng về cảnh tượng lớn, giàu liên tưởng phóng đại.", "Ngữ liệu 1 hướng đến vẻ đẹp thanh tân của cảnh vật; ngữ liệu 2 hướng đến vẻ đẹp rực rỡ, sống động của thiên nhiên."], "correctIndex": 1, "explain": "<b>Câu 7 chọn B</b> Giải thích: Theo bảng đáp án cung cấp, phương án B được xác định là đáp án đúng. Có thể hiểu rằng sự khác biệt về cảm nhận &quot;ấn tượng thoáng nhẹ, hàm súc&quot; hay &quot;rộng mở, kì vĩ&quot; không phải là điểm khác biệt cốt lõi nhất được vạch ra so với các tiêu chí mô tả hình thức (âm thanh, màu sắc, ánh sáng, độ cao) trong ngữ cảnh câu hỏi này"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>nỗi sỉ nhục buốt lòng</i><br><i>khi thấy mẹ ta bảy mươi tuổi lưng còng</i><br><i>phải làm việc mệt nhoài dưới nắng</i><br><i>khi thấy lũ em ngày càng hư hỏng</i><br><i>khi người mình yêu</i><br><i>nói vào mặt mình những lời ti tiện</i><br><i>khi bao điều tưởng thiêng liêng trong sạch</i><br><i>bỗng trở nên ngu xuẩn đê hèn</i><br><i>khinh mọi người và tự khinh mình</i><br><i>như chính tay ta đã gây ra mọi việc</i><br><i>và tất cả không cách nào cứu vãn</i><br><i>nỗi sỉ nhục ngập tràn trái đất</i><br><i>khi lẽ phải luôn thuộc về kẻ mạnh</i><br><i>những nền văn minh chạy theo dục vọng</i><br><i>những guồng máy xấu xa chà đạp con người</i><br>(Những điều sỉ nhục và căm giận, Lưu Quang Vũ)<br>Đâu không phải là nội dung có thể suy ra từ đoạn thơ trên?", "choices": ["Chủ thể trữ tình cảm nhận nỗi đau trong các quan hệ gần gũi, từ gia đình đến tình yêu và những giá trị từng tin tưởng.", "Đoạn thơ cho thấy sự đổ vỡ của niềm tin khi con người nhận ra những điều từng được tôn quý có thể bị biến dạng trong một thực tại thấp kém.", "Cảm xúc trong đoạn thơ có sự vận động từ nỗi đau riêng tư đến sự phẫn uất trước một trật tự xã hội bất công - con người bị nghiền nát bởi quyền lực.", "Đoạn thơ thể hiện mặc cảm tội lỗi của chủ thể trữ tình vì cho rằng chính mình là căn nguyên gây ra những đổ vỡ trong đời sống."], "correctIndex": 3, "explain": "<b>Câu 8 chọn D</b> Giải thích: Câu thơ viết &quot;khinh mọi người và tự khinh mình / như chính tay ta đã gây ra mọi việc&quot; thể hiện sự bất lực và day dứt tột cùng (từ &quot;như&quot;), chứ không khẳng định chủ thể trữ tình thực sự là căn nguyên gây ra sự đổ vỡ."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Để rồi bao nhiêu gió thổi<br>Bên giếng làng, ngoài bến sông<br>Có tiếng hát như con gái<br>Cao cao như vầng trăng trong...<br>(Miền quê, Nguyễn Khoa Điềm)<br>Biện pháp tu từ nào KHÔNG có trong khổ thơ trên?", "choices": ["Điệp thanh", "So sánh", "Đối", "Nhân hoá."], "correctIndex": 3, "explain": "<b>Câu 9 chọn D</b> Giải thích: Khổ thơ sử dụng biện pháp điệp từ (&quot;như&quot;), điệp thanh (&quot;cao cao&quot;), và so sánh (&quot;tiếng hát như con gái&quot;, &quot;như vầng trăng trong&quot;). Tuy nhiên, không có hình ảnh hay sự vật nào được nhân hóa"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Bây giờ thì cái tác phẩm mới của tôi đã hoàn thành. Tôi đang đối mặt với chính mình, để viết những dòng này, như những lời chú giải cho một tác phẩm hội họa thể hiện một cái mặt người rất lớn: những luồng ánh sáng hàng nghìn nến từ phía trước và trên đầu chiếu thẳng xuống một nửa mái đầu tóc tốt rợp như một khu rừng đen bí ẩn, và một nửa mái tóc đã cắt, thoạt trông như một phần bộ óc mầu xám vừa bị mổ phanh ra. Phần bên dưới khuôn mặt như vẫn đang được giấu kín dưới một cái mặt nạ: dưới cằm và hai bên mép phủ kín bọt xà phòng. Không trông rõ miệng, chỉ thấy một vệt mầu đen lờ mờ nổi bồng bềnh trên những đám bọt xà phòng. Và nổi bật trên cái khuôn mặt là đôi mắt mở to, khắc khoải, bồn chồn, đầy nghiêm khắc, đang nhìn vào nội tâm.”</i><br>(Bức tranh, Nguyễn Minh Châu)<br>Đặc trưng nào của văn học Việt Nam sau 1975 được thể hiện nổi bật nhất qua đoạn trích trên?", "choices": ["Khuynh hướng nhận thức lại hiện thực qua những tình huống đời tư và trải nghiệm cá nhân.", "Sự quan tâm đến đời sống bên trong tâm hồn với chiều kích đa diện, phức tạp.", "Cảm hứng thế sự, đời tư thay thế dần cho cảm hứng sử thi trước đó.", "Sự mở rộng khả năng phản ánh những số phận cá nhân trong đời sống hậu chiến."], "correctIndex": 2, "explain": "<b>Câu 10 chọn C</b> Giải thích: Đoạn trích khắc họa sâu sắc sự đối diện với nội tâm, phân tích bản ngã phức tạp của con người (bức tranh nửa đen tối, nửa xám xịt bị mổ phanh). Điều này tiêu biểu cho sự chuyển hướng từ cảm hứng sử thi sang cảm hứng thế sự, đời tư trong văn học sau 1975."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn phương án đúng chính tả", "choices": ["nói khoát, khoát tay", "nói khoác, khoác tay", "nói khoát, khoác tay", "nói khoác, khoát tay"], "correctIndex": 3, "explain": "<b>Câu 11 chọn D</b> Giải thích: &quot;Nói khoác&quot; có nghĩa là nói phóng đại, nói phét. &quot;Khoát tay&quot; là hành động vung tay dứt khoát. Vì vậy, &quot;nói khoác, khoát tay&quot; là cách viết đúng chính tả."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn từ phương án chứa từ “hư” không cùng nét nghĩa với những từ còn lại.", "choices": ["hư danh", "hư vô", "khiêm hư", "sinh hư"], "correctIndex": 3, "explain": "<b>Câu 12 chọn D</b> Giải thích: Chữ &quot;hư&quot; trong <i>hư danh</i>, <i>hư vô</i>, <i>khiêm hư</i> đều mang nghĩa là trống rỗng, không có thực hoặc nhún nhường. Trong khi đó, &quot;hư&quot; trong <i>sinh hư</i> mang nghĩa là hỏng, nhiễm thói xấu."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“<i>Việc anh mắng con trước mặt mọi người chỉ vì một lỗi nhỏ là hơi quá đáng, đúng là ít xít ra nhiều.”</i><br>Câu trên là câu mắc lỗi gì?", "choices": ["Dùng từ/thành ngữ sai nghĩa", "Dùng từ không phù hợp với khả năng kết hợp của từ", "Dùng từ/thành ngữ sai chính tả", "Dùng từ không phù hợp với phong cách."], "correctIndex": 1, "explain": "<b>Câu 13 chọn B</b> Giải thích: Thành ngữ đúng phổ biến là &quot;chuyện bé xé ra to&quot;. Việc tác giả ghép thành &quot;ít xít ra nhiều&quot; là sự kết hợp từ không phù hợp với quy tắc kết hợp của các thành ngữ/tục ngữ cố định trong tiếng Việt."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>“Nhưng thương nhớ kì lạ lắm. Có những đêm không ngủ, nằm nghe tiếng mưa rơi, tôi cố nhớ lại nét mặt của người thương, mà không hiểu tại sao con mắt, miệng cười và mớ tóc xoã trên bờ vai tròn trĩnh lại lu mờ như thể chìm đắm trong khói sương. Mà trái lại có những kỉ niệm rất bé nhỏ, rất tầm thường lại hiện ra rõ rệt, không suy suyển một ly trong trí óc của người nặng nợ lưu ly, nằm buồn trong gác nhỏ ngâm câu thơ nhớ vợ:<br>Ủ ê nét liễu sầu tuôn gió<br>Thổn thức tình tơ lệ ướt đào.<br>Hoa tủi còn đâu duyên tác hợp,<br>Mây bay rồi nữa giấc chiêm bao!”<br>(Thương nhớ Mười Hai, Vũ Bằng)<br>Có bao nhiêu từ láy trong đoạn trích trên?", "choices": ["3", "4", "5", "6"], "correctIndex": 2, "explain": "<b>Câu 14 chọn C</b> Giải thích: Trong đoạn trích có các từ láy là: <i>kì lạ, tròn trĩnh, suy suyển, thổn thức, ủ ê</i> (tổng cộng 5 từ láy)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đâu là câu đúng trong các câu sau?", "choices": ["Mỗi lần về đến quê nhà, ngoại đã đứng chờ tôi ở cửa.", "Cơn đau nơi lồng ngực âm ĩ, thi thoảng lại dội lên đau nhói.", "Trên cây cành của sở thú, những con khỉ sổng chuồng vắt vẻo.", "Những phàn nàn về nhà ở của dân cư vẫn chưa được giải quyết."], "correctIndex": 2, "explain": "<b>Câu 15 chọn C</b> Giải thích: So với các câu mắc lỗi logic thời gian (Câu A), lỗi chính tả &quot;âm ĩ&quot; thay vì &quot;âm ỉ&quot; (Câu B), hoặc diễn đạt lủng củng (Câu D), câu C có cấu trúc ngữ pháp trọn vẹn và đúng nhất trong các lựa chọn được đưa ra."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><b>Mẹ</b><br>Mồ hôi mẹ<br>Tháng ngày đăm đăm<br>nhỏ giọt<br>Con níu - giọt mồ hôi<br>Ðứng dậy làm người.<br>(Phùng Cung)<br>Tác dụng nổi bật của việc mở rộng khả năng kết hợp của từ thể hiện qua từ “níu” là gì?", "choices": ["Làm cho hình ảnh “mồ hôi mẹ” không chỉ là dấu hiệu lao động vất vả mà còn trở thành điểm tựa tinh thần nâng đỡ sự trưởng thành của con.", "Nhấn mạnh sự mệt nhọc kéo dài của người mẹ qua thời gian, từ đó tạo giọng thơ xót xa, thương cảm.", "Gợi tả cụ thể dáng vẻ người con đang bám víu vào mẹ để tập đi trong những năm tháng đầu đời.", "Làm nổi bật sự đối lập giữa nỗi vất vả của mẹ và sự vô tâm của người con khi trưởng thành."], "correctIndex": 0, "explain": "<b>Câu 16 chọn A</b> Giải thích: Từ &quot;níu&quot; thường dùng với hành động cầm nắm vật thể cụ thể. Việc kết hợp &quot;níu - giọt mồ hôi&quot; (một yếu tố trừu tượng hóa sự hy sinh của mẹ) giúp hình tượng hóa sự nhọc nhằn của mẹ thành điểm tựa vững chắc để con khôn lớn."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Vở kịch lấy đi nhiều nước mắt của nghệ sĩ Thành Lộc đã trở thành kí ức đẹp đẽ trong tuổi thơ những người yêu kịch.”<br>Đây là câu _________.<br>Hãy chọn phương án để điền vào chỗ trống.", "choices": ["sai ngữ pháp", "sai logic", "mơ hồ cấu trúc", "sai quy chiếu."], "correctIndex": 2, "explain": "<b>Câu 17 chọn C</b> Giải thích: Câu văn mắc lỗi mơ hồ về mặt cấu trúc. Không rõ nghệ sĩ Thành Lộc là khán giả (xem kịch rồi khóc) hay là người diễn viên/đạo diễn làm nên vở kịch khiến khán giả khóc"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Các bạn ngửi thấy</i><b><i>, khi đi qua những cánh đồng xanh, mà hạt thóc nếp đầu tiên làm trĩu thân lúa còn tươi,</i></b><i> ngửi thấy cái mùi thơm mát của bông lúa non không?</i><br>(Thạch Lam)<br>Thành phần in đậm là thành phần gì?", "choices": ["Vị ngữ", "Thành phần phụ chú", "Thành phần chêm xen", "Trạng ngữ."], "correctIndex": 3, "explain": "<b>Câu 18 chọn D</b> Giải thích: Cụm từ &quot;khi đi qua những cánh đồng xanh...&quot; mở đầu bằng từ &quot;khi&quot;, đứng trước chủ ngữ nhằm chỉ thời gian và không gian xảy ra hành động &quot;ngửi thấy&quot;. Do đó, đây là thành phần Trạng ngữ."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>Đôi mắt người Sơn Tây<br>U uẩn chiều lưu lạc<br>Buồn viễn xứ khôn ______<br>Tôi gửi niềm nhớ thương<br>Em mang giùm tôi nhé<br>Ngày trở lại quê ________<br>Khúc hoàn ca rớm lệ<br>(Đôi mắt người Sơn Tây, Quang Dũng)<br>Hai từ phù hợp đièn vào chỗ trống là gì?", "choices": ["khuây – hương", "nguôi – nhà", "nguôi – hương", "khuây – hè"], "correctIndex": 0, "explain": "<b>Câu 19 chọn A</b> Giải thích: Dựa vào nguyên tác bài thơ &quot;Đôi mắt người Sơn Tây&quot; của Quang Dũng, hai từ cần điền để hoàn thiện khổ thơ và đảm bảo niêm luật, vần điệu là &quot;khuây&quot; (khôn khuây) và &quot;hương&quot; (quê hương)"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Trong giai đoạn từ cuối thế kỉ XIX đến những năm 50, người ta quan tâm đến việc chú thích vì giúp độc giả hiểu được văn lí, vì để tồn cổ, vì độc giả hiện đại ngày càng xa dần vốn văn chương cổ. </i>(Trần Đình Sử)<br>Trong câu trên, từ “văn lí” được hiểu là gì?", "choices": ["Lí thuyết nghiên cứu các thể loại văn học", "Mạch ý và ý nghĩa trong văn bản.", "Những quy tắc gieo vần và niêm luật trong thơ cổ.", "Tiểu sử tác giả và hoàn cảnh ra đời tác phẩm."], "correctIndex": 1, "explain": "<b>Câu 20 chọn B</b> Giải thích: Trong việc tiếp nhận văn chương cổ, &quot;văn lí&quot; được hiểu là mạch ý, logic cấu tứ và ý nghĩa sâu xa được truyền tải bên trong văn bản."}], "khongXaoTron": true}, {"noiDungChung": "Khả năng nhận biết cảm xúc và kết nối xã hội đóng vai trò quan trọng trong sự phát triển toàn diện của trẻ. Dưới đây là những dấu hiệu trẻ phát triển trí tuệ cảm xúc từ sớm.<br><b>Thể hiện cảm xúc cơ bản</b><br>Trí tuệ cảm xúc ở trẻ nhỏ bắt đầu từ khả năng nhận biết và thể hiện cảm xúc của bản thân. Thay vì chỉ khóc hoặc phản ứng bộc phát, trẻ dần biết sử dụng lời nói, hành động hay nét mặt để bày tỏ cảm xúc vui vẻ, buồn bã hoặc tức giận.<br><b>Thể hiện sự đồng cảm với người khác</b><br>Khi nhận thấy người khác đang buồn hay khóc và có hành động quan tâm như ôm, vỗ về hoặc rủ chơi cùng, trẻ đang thể hiện sự phát triển trí tuệ cảm xúc. Những hành vi này cho thấy bé bắt đầu nhận biết và phản hồi với cảm xúc của người xung quanh một cách tích cực.<br><b>Bình tĩnh khi được hỗ trợ</b><br>Trẻ có phản ứng tích cực với sự an ủi, hướng dẫn từ cha mẹ như dễ bình tĩnh lại khi được nói chuyện nhẹ nhàng hoặc ôm ấp. Điều này cho thấy trẻ đang học cách điều chỉnh cảm xúc. Theo thời gian, bé sẽ dần biết xoa dịu bản thân khi gặp các tình huống gây căng thẳng.<br><b>Dùng lời nói thay vì phản ứng thể chất</b><br>Trẻ dần thay thế các phản ứng thể chất khi tức giận, tổn thương hoặc có nhu cầu bằng ngôn ngữ. Việc sử dụng những từ đơn giản như &quot;không&quot;, &quot;giúp con&quot; cho thấy trẻ bày tỏ mong muốn, cảm xúc hoặc nhu cầu hỗ trợ thay vì phản ứng bằng hành vi như bỏ chạy hay khóc lóc.”<br>(Theo Lê Nguyễn, “Dấu hiệu trẻ đang phát triển trí tuệ cảm xúc”, VnExpress Sức khỏe, 09/02/2026.)", "cauHoi": [{"question": "Theo văn bản, biểu hiện nào được xem là khởi đầu của trí tuệ cảm xúc ở trẻ nhỏ?", "choices": ["Khả năng giữ bình tĩnh trong mọi tình huống", "Khả năng nhận biết và thể hiện cảm xúc của bản thân", "Khả năng sử dụng ngôn ngữ phức tạp để diễn đạt suy nghĩ", "Khả năng phản ứng nhanh với mọi kích thích từ môi trường."], "correctIndex": 1, "explain": "<b>Câu 21 chọn B</b> Giải thích: Dựa vào câu văn trong văn bản: &quot;Trí tuệ cảm xúc ở trẻ nhỏ bắt đầu từ khả năng nhận biết và thể hiện cảm xúc của bản thân&quot; , phương án B là đáp án chính xác."}, {"question": "Chi tiết “vỗ về hoặc rủ chơi cùng” trong văn bản chủ yếu cho thấy điều gì?", "choices": ["Trẻ có xu hướng né tránh cảm xúc tiêu cực của người khác", "Trẻ bước đầu biết phản hồi với cảm xúc của người xung quanh một cách tích cực", "Trẻ đã có khả năng kiểm soát hoàn toàn cảm xúc của bản thân", "Trẻ thường hành động theo thói quen hơn là theo cảm xúc"], "correctIndex": 1, "explain": "<b>Câu 22 chọn B</b> Giải thích: Văn bản nêu rõ rằng khi trẻ có hành động quan tâm, ôm ấp hoặc rủ chơi cùng người đang buồn, những hành vi này &quot;cho thấy bé bắt đầu nhận biết và phản hồi với cảm xúc của người xung quanh một cách tích cực&quot;"}, {"question": "Cách trình bày thông tin chủ yếu của văn bản là gì?", "choices": ["Trình bày theo cấu trúc phân loại thông tin", "Trình bày theo cấu trúc thông tin chính – thông tin chi tiết", "Trình bày theo lối liệt kê – quy nạp", "Trình bày theo cấu trúc so sánh đối chiếu"], "correctIndex": 1, "explain": "<b>Câu 23 chọn B</b> Giải thích: Văn bản được tổ chức theo cấu trúc đưa ra vấn đề chính (dấu hiệu trẻ phát triển trí tuệ cảm xúc) , sau đó triển khai bằng các tiêu đề phụ chứa thông tin chi tiết (Thể hiện cảm xúc cơ bản, Thể hiện sự đồng cảm...)."}, {"question": "Nhận định nào sau đây không phù hợp với nội dung văn bản?", "choices": ["Trẻ biết dùng lời nói thay cho phản ứng bùng phát là một dấu hiệu tích cực.", "Việc được cha mẹ hỗ trợ bình tĩnh lại giúp trẻ dần học cách điều chỉnh cảm xúc.", "Khả năng đồng cảm với người khác quan trọng hơn một số dấu hiệu.", "Khả năng nhận biết và biểu lộ cảm xúc của bản thân là một dấu hiệu quan trọng."], "correctIndex": 2, "explain": "<b>Câu 24 chọn C</b><br><b>Giải thích:</b> Văn bản chỉ liệt kê các dấu hiệu của trí tuệ cảm xúc (nhận biết bản thân, đồng cảm, bình tĩnh...) nhưng <b>không hề so sánh</b> xem dấu hiệu nào quan trọng hơn dấu hiệu nào. Do đó, nhận định C không có cơ sở trong bài đọc."}, {"question": "Từ nội dung văn bản, có thể suy ra điều gì?", "choices": ["Trí tuệ cảm xúc của trẻ được hình thành qua cả nhận biết bản thân lẫn tương tác với người khác.", "Chỉ những trẻ biết nói sớm mới có khả năng phát triển trí tuệ cảm xúc tốt.", "Việc trẻ bộc lộ cảm xúc mạnh là dấu hiệu cho thấy trí tuệ cảm xúc kém phát triển.", "Khả năng bình tĩnh của trẻ chủ yếu là do tính cách bẩm sinh quyết định."], "correctIndex": 0, "explain": "<b>Câu 25 chọn A</b><br><b>Giải thích:</b> Nội dung bài đọc thể hiện rõ 2 mảng: khả năng thấu hiểu chính mình (thể hiện cảm xúc, tự dùng lời nói) và quá trình tương tác xã hội (đồng cảm với người khác, nhận sự an ủi từ cha mẹ). Suy ra, trí tuệ cảm xúc được hình thành qua cả hai yếu tố này."}], "khongXaoTron": true}, {"noiDungChung": "<b>CHÊNH LỆCH GIÀU NGHÈO QUÁ MỨC PHÁ HỦY GẮN KẾT XÃ HỘI</b><br>Hai tác giả Wilkinson và Pickett đã so sánh giữa các quốc gia phát triển, cũng như giữa 50 bang của Mỹ, để chỉ ra rằng các vấn đề xã hội hiện đại như bệnh tật, tội phạm, đời sống cộng đồng rời rạc, thiếu niên mang thai v.v... xảy ra nhiều hơn ở những nơi có mức bất bình đẳng cao hơn. Điều đó cũng giải thích vì sao so với các quốc gia phát triển khác thì Mỹ có tuổi thọ trung bình thấp hơn và nhiều nhà tù hơn. Theo Robert Putnam, sự gia tăng bất bình đẳng trong năm thập kỷ qua là một trong những lý do chính phá hủy vốn xã hội, sự gắn kết và tính cộng đồng trong xã hội Mỹ ngày nay.<br>Phân hóa giàu nghèo tạo ra cảm giác bất công. Chỉ cần nhìn vào xuất thân của các sinh viên Trung Quốc đang theo học ở các trường đại học hàng đầu của Mỹ thì có thể thấy giới nào đang có lợi thế trong cuộc đua xã hội, để rồi thế hệ qua thế hệ, ngày càng đào sâu cái hố phân cách.<br>Nhưng ngay cả người giàu cũng không được sống yên ổn trong một xã hội phân hóa cực đoan. Bất công là nguồn gốc của bạo lực. Ở Nam Phi, các biệt thự đều có dây thép gai vây kín chung quanh, trở thành những nhà tù cao cấp. Ở Trung Quốc, dịch vụ đào tạo vệ sĩ cho những gia đình giàu có đang bùng nổ. Ở Mỹ và các nước phương Tây, phong trào Chúng ta là 99% và Occupy cho thấy đám đông đang thực sự nổi giận.<br>Trước những vấn đề này, các quốc gia đã bắt đầu hành động. Cuối 2013, tòa án tối cao Pháp thông qua mức thuế 75% cho tất cả các thu nhập vượt 1 triệu Euro một năm. EU ban hành một điều luật giới hạn mức thưởng ở các ngân hàng chỉ được tối đa bằng hai lần mức lương. Đầu năm 2013, 68% người dân Thụy Sĩ bỏ phiếu cho phép các cổ đông có quyền hạn chế mức lương và thưởng của lãnh đạo công ty. Tổ chức nhân đạo Oxfam của Anh kêu gọi chấm dứt “nạn” giàu có quá mức vào năm 2025 - trong một thế giới với nguồn lực hữu hạn, nghèo đói chỉ có thể được giải quyết nếu chênh lệch giàu nghèo cực đoan được chấm dứt.<br>Sau gần 80 năm, phát biểu của tổng thống Roosevelt vào năm 1936 vẫn còn nguyên tính thời sự: “Sự bình đẳng chính trị mà chúng ta giành được đã vô nghĩa trước sự bất bình đẳng kinh tế. Một nhóm nhỏ gần như hoàn toàn nắm trong tay việc kiểm soát tài sản của người khác, tiền của người khác, sức lao động của người khác - cuộc sống của người khác. Với nhiều người trong chúng ta, cuộc sống không còn tự do nữa, sự giải phóng không còn thực sự nữa, người dân không còn có thể mưu cầu hạnh phúc.”<br>Và vì vậy, thay cho tự hào vì đã có tỉ phú đô la, chúng ta hãy cố gắng để có thể tự hào về mức tăng tuổi thọ trung bình hay số lượng trẻ em tới trường.<br>Trước khi Việt Nam có thể cải thiện các thể chế của mình và diệt trừ tham nhũng để đem lại công bằng và cơ hội cho số đông, về phần mình, ông Phạm Nhật Vượng và những đại gia Việt Nam khác có thể suy nghĩ để học tập Bill Gates hay Warren Buffet trong việc trao tặng của cải. Bởi vì kể cả ngày nào cũng ngủ ở khách sạn Burj Al Arab thì tới mấy đời cũng chẳng thể nào tiêu hết tài sản. Mặt khác, để tới lúc phải chăng dây thép gai dẫn điện quanh dinh thự, và thuê hàng đại đội vệ sĩ đưa con đi học, thì lúc đó đêm đêm ngủ trên cái giường, dẫu 7 tỉ hay 70 tỉ, cũng chẳng sung sướng gì?<br>(Trích Bức xúc không làm ta vô can, Đặng Hoàng Giang.)", "cauHoi": [{"question": "Quan điểm chính của văn bản là gì?", "choices": ["Bất bình đẳng kinh tế khiến người nghèo mất cơ hội vươn lên và làm sâu sắc thêm khoảng cách giữa các tầng lớp xã hội.", "Chênh lệch giàu nghèo quá mức không chỉ gây bất công mà còn phá hủy gắn kết xã hội, làm bất ổn đời sống của cả người nghèo lẫn người giàu.", "Các quốc gia phát triển đã nhận ra hậu quả của bất bình đẳng và bắt đầu dùng chính sách thuế, lương thưởng để điều chỉnh khoảng cách giàu nghèo.", "Việt Nam cần học các tỉ phú phương Tây trong hoạt động thiện nguyện để giảm bớt căng thẳng xã hội do phân hóa tài sản gây ra."], "correctIndex": 1, "explain": "<b>Câu 26 chọn B</b> Giải thích: Nội dung xuyên suốt của bài viết tập trung phân tích hậu quả của chênh lệch giàu nghèo quá mức, không chỉ sinh ra bất công mà còn phá vỡ vốn xã hội, gây ra bạo lực và sự bất an cho mọi tầng lớp, kể cả người giàu."}, {"question": "Việc tác giả nhắc đến Nam Phi, Trung Quốc, Mỹ và các nước phương Tây chủ yếu nhằm làm rõ điều gì?", "choices": ["Phân hóa giàu nghèo không chỉ là vấn đề kinh tế mà còn tạo ra tâm lý bất an, đối kháng và nguy cơ bạo lực trong xã hội.", "Các quốc gia có mức phát triển khác nhau đều đang phải đối mặt với tình trạng người giàu bị đe dọa bởi sự giận dữ của số đông.", "Bạo lực xã hội thường xuất hiện ở những nơi người giàu sống tách biệt trong các khu biệt thự được bảo vệ nghiêm ngặt.", "Người giàu trong xã hội bất bình đẳng phải trả giá bằng sự suy giảm tự do cá nhân và đời sống tinh thần bất ổn."], "correctIndex": 0, "explain": "<b>Câu 27 chọn A</b> Giải thích: Tác giả dẫn chứng Nam Phi (biệt thự rào thép gai), Trung Quốc (đào tạo vệ sĩ), và phương Tây (phong trào 99%) để minh họa rằng bất bình đẳng gây ra sự giận dữ, bất an, đối kháng và nguy cơ bạo lực cao độ."}, {"question": "Nhận định nào sau đây không phù hợp với nội dung văn bản?", "choices": ["Bất bình đẳng kinh tế có thể làm suy yếu vốn xã hội, sự gắn kết và tính cộng đồng.", "Chênh lệch giàu nghèo khiến lợi thế xã hội được truyền từ thế hệ này sang thế hệ khác.", "Những người nghèo có phần quá khích, vô văn hoá khi đe doạ an ninh của những người giàu.", "Giảm bất bình đẳng cực đoan là điều kiện quan trọng để hướng tới một xã hội công bằng và ổn định hơn."], "correctIndex": 2, "explain": "<b>Câu 28 chọn C</b> Giải thích: Văn bản chỉ đề cập đám đông &quot;đang thực sự nổi giận&quot; vì sự phân hóa và bất công xã hội, chứ hoàn toàn không hề có đánh giá hay miệt thị người nghèo là &quot;quá khích, vô văn hóa&quot;."}, {"question": "Câu trích dẫn của Roosevelt trong văn bản có tác dụng lập luận gì?", "choices": ["Nhấn mạnh rằng bình đẳng chính trị có thể trở nên hình thức nếu quyền lực kinh tế tập trung vào một nhóm nhỏ.", "Chứng minh rằng nước Mỹ từ lâu đã không còn là hình mẫu về tự do, giải phóng và mưu cầu hạnh phúc.", "Làm rõ nguyên nhân khiến các phong trào phản kháng xã hội ở phương Tây bùng nổ trong những năm gần đây.", "Đối chiếu giữa bất bình đẳng chính trị và bất bình đẳng kinh tế để đề xuất một mô hình dân chủ mới."], "correctIndex": 0, "explain": "<b>Câu 29 chọn A</b> Giải thích: Trích dẫn của tổng thống Roosevelt được dùng để lập luận rằng quyền bình đẳng chính trị và tự do mưu cầu hạnh phúc sẽ hoàn toàn bị vô hiệu hóa (trở nên vô nghĩa) nếu kinh tế bị kiểm soát bất công bởi một nhóm thiểu số."}, {"question": "Đâu là phương án phản biện phù hợp nhất với quan điểm của văn bản?", "choices": ["Việc kêu gọi người giàu chia sẻ tài sản có ý nghĩa đạo đức, nhưng khó tạo ra thay đổi bền vững nếu không đi cùng cải cách thể chế và cơ chế phân phối cơ hội.", "Các chính sách hạn chế thu nhập quá cao có thể giảm bất bình đẳng, nhưng cũng cần được cân nhắc để không làm suy yếu động lực sáng tạo và đầu tư.", "Việc đề cao tuổi thọ trung bình hay số lượng trẻ em tới trường là cần thiết, nhưng các chỉ số ấy chưa phản ánh đầy đủ chất lượng phát triển của một xã hội.", "Bất bình đẳng giàu nghèo có thể gây bất ổn xã hội, nhưng không phải mọi khoảng cách thu nhập đều dẫn đến cảm giác bất công hoặc bạo lực."], "correctIndex": 0, "explain": "<b>Câu 30 chọn A</b> Giải thích: Tác giả đề xuất các đại gia tự giác làm từ thiện như Bill Gates. Lời phản biện sâu sắc và logic nhất cho đề xuất này là: Lòng tốt cá nhân khó đem lại sự công bằng bền vững; vấn đề gốc rễ vẫn đòi hỏi phải có sự cải cách mạnh mẽ về mặt thể chế và phân phối cơ hội."}], "khongXaoTron": true}], "anh": [{"noiDungChung": "<b>Questions 31-35: Choose a suitable word or phrase (A, B, C, or D) to fill in each blank.</b>", "cauHoi": [{"question": "The manager found that _____ resources were necessary to meet the growing demand for the product.", "choices": ["little", "each", "a lot of", "a few of."], "correctIndex": 2, "explain": "<b>Câu 31 chọn C</b><br><b>Giải thích:</b> &quot;Resources&quot; (tài nguyên) là danh từ đếm được số nhiều. &quot;A lot of&quot; dùng được cho cả danh từ đếm được và không đếm được, hoàn toàn phù hợp với ngữ cảnh câu (cần <i>nhiều</i> tài nguyên).<br><b>Lưu ý quan trọng:</b> &quot;A few of&quot; bắt buộc phải đi kèm với từ hạn định phía sau (ví dụ: a few of <i>the/these/my</i> resources)"}, {"question": "If you want to maintain a healthy lifestyle, it&#x27;s important to engage in _____.", "choices": ["regular physical activity", "activate physically regular", "actively physical regularity", "active regular physicality"], "correctIndex": 0, "explain": "<b>Câu 32 chọn A</b><br><b>Giải thích:</b> Sau giới từ &quot;in&quot; cần một cụm danh từ. &quot;Regular physical activity&quot; (hoạt động thể chất thường xuyên) là một cụm danh từ chuẩn xác.<br><b>Công thức chung:</b> Adjective + Adjective + Noun."}, {"question": "Emma is _____ her classmate, Sarah, which is why she often scores higher on exams and assignments.", "choices": ["older and more experienced than", "more older and experienced than", "more experienced and older than", "the more experienced and older than."], "correctIndex": 0, "explain": "<b>Câu 33 chọn A</b><br><b>Giải thích:</b> Đây là cấu trúc so sánh hơn với hai tính từ được nối bằng &quot;and&quot;. Theo quy tắc tự nhiên, tính từ ngắn (older) sẽ đứng trước tính từ dài (more experienced)."}, {"question": "There are reports that a tech company plans to _____ the startup I&#x27;m currently employed at.", "choices": ["take over", "cut back", "make up", "fall behind."], "correctIndex": 0, "explain": "<b>Câu 34 chọn A</b><br><b>Giải thích:</b> Dựa vào ngữ cảnh công ty công nghệ có kế hoạch với một công ty khởi nghiệp (startup). Phrasal verb &quot;take over&quot; (tiếp quản, mua lại/sáp nhập) là hợp lý nhất."}, {"question": "By the time you finish setting up the party, they _____ all the decorations.", "choices": ["complete", "have completed", "will complete", "will have completed"], "correctIndex": 3, "explain": "<b>Câu 35 chọn D</b><br><b>Giải thích:</b> Dấu hiệu nhận biết là cụm &quot;By the time&quot; (tính đến lúc). Mệnh đề đi với By the time đang ở thì hiện tại đơn (finish), do đó mệnh đề chính phải lùi về thì Tương lai hoàn thành (sẽ đã làm xong một việc gì đó trong tương lai).<br><b>By the time + S + V (Hiện tại đơn), S + will have + V3/ed.</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Questions 36-40: Each of the following sentences has one error (A, B, C, or D). Find it and blacken your choice on your answer sheet.</b>", "cauHoi": [{"question": "The reason <u>that</u> the project was delayed <u>was</u> <u>due to</u> unexpected complications <u>with</u> the suppliers.", "choices": ["that", "was", "due to", "with."], "correctIndex": 2, "explain": "<b>Câu 36 chọn C</b><br><b>Giải thích:</b> Lỗi sai ở cụm &quot;due to&quot;. Trong tiếng Anh, cấu trúc &quot;The reason... is due to...&quot; bị lặp nghĩa (redundancy) vì cả hai đều chỉ nguyên nhân.<br><b>Cách sửa:</b> Đổi &quot;due to&quot; thành &quot;that&quot; hoặc bỏ hẳn (The reason that the project was delayed was <b>that</b>...)."}, {"question": "The <u>sick</u> cat <u>tried</u> to stand up on <u>their</u> legs, but it <u>quickly</u> sat back down.", "choices": ["sick", "tried", "their", "quickly."], "correctIndex": 2, "explain": "<b>Câu 37 chọn C</b><br><b>Giải thích:</b> Chủ ngữ &quot;The sick cat&quot; là danh từ số ít (tương đương đại từ &quot;it&quot;), do đó tính từ sở hữu đi theo nó không thể là &quot;their&quot;.<br><b>Cách sửa:</b> Đổi &quot;their&quot; thành &quot;its&quot;."}, {"question": "She is <u>the</u> professor <u>at a</u> prestigious university, <u>specializing</u> in <u>the field</u> of quantum physics.", "choices": ["the", "at a", "specializing", "the field."], "correctIndex": 0, "explain": "<b>Câu 38 chọn A</b><br><b>Giải thích:</b> Khi giới thiệu nghề nghiệp của một người nói chung mà chưa xác định đó là người duy nhất giữ chức vụ đó, ta dùng mạo từ không xác định &quot;a/an&quot;.<br><b>Cách sửa:</b> Đổi &quot;the&quot; thành &quot;a&quot; (She is <b>a</b> professor...)."}, {"question": "&quot;A <u>number</u> of students in the program <u>has chosen</u> to participate <u>in</u> the <u>prestigious</u> international exchange initiative.&quot;", "choices": ["A number", "has chosen", "in", "prestigious"], "correctIndex": 1, "explain": "<b>Câu 39 chọn B</b><br><b>Giải thích:</b> Cấu trúc &quot;A number of&quot; luôn đi với động từ chia ở số nhiều.<br><b>Cách sửa:</b> Đổi &quot;has chosen&quot; thành &quot;have chosen&quot;.<br><b>Lưu ý quan trọng:</b> Phân biệt với &quot;The number of&quot; + N (số nhiều) + V (chia số ít)."}, {"question": "The <u>professor findings</u> in the research <u>were</u> <u>groundbreaking</u> and <u>widely</u> discussed.", "choices": ["professor findings", "were", "groundbreaking", "widely"], "correctIndex": 0, "explain": "<b>Câu 40 chọn A</b><br><b>Giải thích:</b> Cần một Sở hữu cách để chỉ &quot;những phát hiện <i>của</i> giáo sư&quot;. Đứng trước danh từ &quot;findings&quot; không thể ghép trực tiếp danh từ &quot;professor&quot; như vậy.<br><b>Cách sửa:</b> Đổi &quot;professor findings&quot; thành &quot;professor&#x27;s findings&quot;."}], "khongXaoTron": true}, {"noiDungChung": "<b>Questions 41-45: Which of the following best restates each of the given sentences?</b>", "cauHoi": [{"question": "&quot;I spent a large amount of money on this valueless book.&quot; said Falla.", "choices": ["Falla denied spending a large amount of money on that valueless book.", "Falla promised to spend a large amount of money on that valueless book.", "Falla admitted having spent a large amount of money on that valueless book.", "Falla regretted not having spent a large amount of money on that valueless book."], "correctIndex": 2, "explain": "<b>Câu 41 chọn C</b><br><b>Giải thích:</b> Câu gốc: &quot;Tôi đã tiêu một số tiền lớn vào cuốn sách vô giá trị này&quot;. Đây là một lời thú nhận về hành động đã làm trong quá khứ.<br><b>Công thức chung:</b> Admit + V-ing / having + V3/ed (Thú nhận đã làm gì)."}, {"question": "You must study hard, or you will not pass the final exam.", "choices": ["Unless you study hard, you will not pass the final exam.", "But for your hard work, you will not pass the final exam.", "Otherwise, you will not pass the final exam if you do not study hard.", "If you study hard, you will pass the final exam."], "correctIndex": 0, "explain": "<b>Câu 42 chọn A</b><br><b>Giải thích:</b> Câu gốc: &quot;Bạn phải học chăm, nếu không bạn sẽ trượt.&quot; Tương đương với: &quot;Trừ khi bạn học chăm, (nếu không) bạn sẽ trượt.&quot;<br><b>Công thức chung:</b> Unless + S + V (khẳng định) = If + S + don&#x27;t/doesn&#x27;t + V."}, {"question": "This restaurant serves the best food in town.", "choices": ["No other restaurant in town serves better food than this one.", "This restaurant serves food as good as any other in town.", "The food at this restaurant is worse than the food at other restaurants.", "This restaurant is better than many restaurants in town."], "correctIndex": 0, "explain": "<b>Câu 43 chọn A</b><br><b>Giải thích:</b> Câu gốc dùng So sánh nhất: &quot;Nhà hàng này phục vụ đồ ăn ngon nhất thị trấn.&quot; Tương đương với câu So sánh hơn: &quot;Không có nhà hàng nào khác trong thị trấn phục vụ đồ ăn ngon hơn nhà hàng này.&quot;"}, {"question": "The committee had already made the decision before the board of directors were informed.", "choices": ["The decision had already been made by the committee before the board of directors were informed.", "The committee had already made the decision before the board of directors had been informed.", "The decision was already made by the committee before the board of directors were informed.", "The decision had been made before the board of directors had been informed by the committee."], "correctIndex": 0, "explain": "<b>Câu 44 chọn A</b><br><b>Giải thích:</b> Biến đổi từ câu chủ động sang câu bị động ở thì Quá khứ hoàn thành.<br><b>Công thức chung:</b> S + had + already + been + V3/ed."}, {"question": "The company&#x27;s profits have decreased, definitely due to the recent price increase.", "choices": ["The price increase could have caused the company&#x27;s profit to decrease.", "The price increase must be the cause of the company&#x27;s profit decrease.", "The company&#x27;s decrease in profits must be associated with the recent price increase.", "It is possible that the recent price increase resulted in decreased profits for the company."], "correctIndex": 1, "explain": "<b>Câu 45 chọn B</b><br><b>Giải thích:</b> Câu gốc có từ &quot;definitely&quot; (chắc chắn). Để thể hiện sự suy luận/phỏng đoán chắc chắn ở hiện tại, ta dùng động từ khuyết thiếu &quot;must&quot;. &quot;The price increase <b>must be</b> the cause...&quot;."}], "khongXaoTron": true}, {"noiDungChung": "<b>Questions 46-52: Read the passage carefully.</b><br>It is normal to feel nervous before an interview, especially if you are entering the world of work for the first time. However, you can save yourself a lot of stress and anxiety by doing a few simple things. Apart from praying, here is some advice you could take into consideration the next time you have to go for a job interview.<br>The key to a successful interview is preparation. It is very important to make sure <b><u>your</u></b> CV is up-to-date and free of mistakes. Also, you should make use of the Internet, as well as magazines and newspapers, in order to gather information about the company or organization you are applying to. Furthermore, you must know some things about the specific job position, including general responsibilities and daily duties.<br>Next, it is helpful to prepare for the interview itself by answering typical interview questions. You can try answering these specific questions in front of a friend or family member. Videotaping yourself might help you as well. Remember, there is always room for improvement; the more you practice, the more confident you will be that you won&#x27;t mess things up during the interview. You should also prepare questions to ask during the interview. These questions should <b><u>reflect</u></b> your research on the company and position. However, remember not to ask any questions about salary on your first interview. If you do, the interviewer may think that you only care about the benefits and that your interest in the company isn&#x27;t genuine.<br>Final preparations include choosing what to wear. It is important to select something appropriate. A business suit is always acceptable. If your clothing is clean and well pressed, the interviewer will think that you are a neat and organized person. Also, you must know the location of your interview. You should arrive at the interview ten minutes in advance. You must also remember to bring extra copies of your CV with you. Bringing a small notebook for notes is also a good idea. Remember to stay calm and project an image of self-confidence. In it, you should emphasize your interest and restate your specific qualifications for the position. Remember, the more you prepare, the more successful your interview will be.<br>(Adapted from: Traveler 3 by H. Q. Mitchell)", "cauHoi": [{"question": "What is the passage mainly about?", "choices": ["Strategies to alleviate interview stress", "The importance of preparation for job interviews", "Common mistakes to avoid during an interview", "The role of appearance in interview success"], "correctIndex": 1, "explain": "<b>Câu 46 chọn B</b><br><b>Giải thích:</b> Toàn bộ bài đọc tập trung vào các bước và tầm quan trọng của việc chuẩn bị trước, trong và sau khi phỏng vấn (chuẩn bị CV, tìm hiểu công ty, luyện tập câu hỏi, trang phục)."}, {"question": "In paragraph 1, the author suggests that nervousness before an interview is primarily the result of ------------.", "choices": ["Overestimating the importance of interviews in the hiring process", "Lack of preparation and insufficient knowledge about the company", "The pressure of entering the workforce for the first time", "The possibility of failing to meet the interviewer&#x27;s expectations"], "correctIndex": 2, "explain": "<b>Câu 47 chọn C</b><br><b>Giải thích:</b> Dựa vào câu đầu tiên của đoạn 1: &quot;...especially if you are entering the world of work for the first time&quot; (đặc biệt nếu bạn bước vào thế giới công việc lần đầu tiên)."}, {"question": "The word &quot;<b><u>your</u></b>&quot; in paragraph 2 refers to", "choices": ["the interviewer&#x27;s", "the company&#x27;s", "the candidate&#x27;s", "the friend&#x27;s."], "correctIndex": 2, "explain": "<b>Câu 48 chọn C</b><br><b>Giải thích:</b> &quot;your CV&quot; (CV của bạn). Đại từ &quot;your&quot; ở đây đang ám chỉ trực tiếp người đọc bài viết - chính là ứng viên phỏng vấn (the candidate)."}, {"question": "In paragraph 2, the author emphasizes the importance of preparation by advising candidates to", "choices": ["Focus primarily on making a good first impression rather than on job-related knowledge", "Ensure their CV is free of errors and learn about the company and position", "Avoid practicing interview questions to maintain spontaneity", "Wait for the interviewer to ask about qualifications instead of volunteering information."], "correctIndex": 1, "explain": "<b>Câu 49 chọn B</b><br><b>Giải thích:</b> Dựa vào đoạn 2: Tác giả khuyên &quot;...make sure your CV is up-to-date and free of mistakes&quot; và &quot;...gather information about the company...&quot;."}, {"question": "The word &quot;<b><u>reflect</u></b>&quot; in paragraph 3 is closest in meaning to__________", "choices": ["conceal", "exhibit", "question", "disregard."], "correctIndex": 1, "explain": "<b>Câu 50 chọn B</b><br><b>Giải thích:</b> &quot;reflect&quot; (phản ánh, cho thấy) đồng nghĩa với &quot;exhibit&quot; (trưng bày, thể hiện). Các câu hỏi bạn đặt ra cần phải <i>thể hiện</i> được rằng bạn có nghiên cứu về công ty."}, {"question": "According to paragraph 3, why should you avoid asking about salary during the first interview?", "choices": ["It indicates that you have not thoroughly researched the organization", "It might imply that your primary motivation is the financial benefits", "It is perceived as being overly forward and untimely", "It could result in the interviewer forming a negative perception of your priorities."], "correctIndex": 3, "explain": "<b>Câu 51 chọn D</b><br><b>Giải thích:</b> Dựa vào câu cuối đoạn 3: &quot;If you do, the interviewer may think that you only care about the benefits...&quot; (Người phỏng vấn có thể nghĩ bạn chỉ quan tâm đến lợi ích và hình thành cái nhìn tiêu cực về ưu tiên của bạn)."}, {"question": "Which of the following can be inferred from the passage?", "choices": ["Thorough preparation for an interview greatly increases the likelihood of success.", "Discussing salary in the first interview can be seen as unprofessional.", "Taking advantage of the Internet is required to gather information about the company.", "A well-groomed appearance positively influences the interviewer&#x27;s decision."], "correctIndex": 0, "explain": "<b>Câu 52 chọn A</b><br><b>Giải thích:</b> Suy luận từ câu kết luận của toàn bài: &quot;Remember, the more you prepare, the more successful your interview will be.&quot; (Sự chuẩn bị kỹ lưỡng làm tăng khả năng thành công)."}], "khongXaoTron": true}, {"noiDungChung": "<b>Questions 53-60: Read the passage carefully.</b><br>Birth order and success<br>If asked, most parents would say that they love and treat all their children equally. However, according to several experts in psychology, a child&#x27;s position in the birth order has an impact on his or her personality, behavior, learning, and ultimately the child&#x27;s career path. Conventional wisdom says that there are natural differences in the way that birth order affects people. For example, parents often <b><u>keep tabs on</u></b> first-born children, while children born later typically have fewer rules. Furthermore, many people believe that the youngest child seems to get away with murder because parents have experienced everything before.<br>But is there truth to this theory that birth order can affect our personalities? Ben Dattner, a psychologist based in New York, believes there is. He says, &quot;Depending on birth order, there are special roles within families, leading to different adaptation patterns and different personalities.&quot; He believes that the stricter upbringing of first-born children leads to <b><u>them</u></b> being more extroverted and confident. They also tend to be more responsible because their parents rely on them to help with the younger children. As a result, first-born children usually have some power over younger siblings, who may even look up to them as substitute parents.<br>Second-born, and middle children, often feel overlooked by their parents, especially if another child is born before they are two years old. Second-born children are not given as much responsibility as first-born children. According to Dattner, they are more accommodating and they are also receptive to new experiences. Many second-born children are quiet, and they prefer to observe instead of participate in family dramas.<br>The youngest child is usually the most creative. Dattner believes this is a result of the more relaxed attitude their parents often have towards them. They are given freedom to experiment in play and they often have fewer restrictions. However, youngest children tend to enjoy the attention they receive, and this can cause them to be manipulative to get what they want.<br>Clearly, birth order can affect personality, but what about career advancement and success? Michael Grose, author of Why Firstborns Rule the World and Last Borns Want to Change It, strongly believes that birth order affects career choices and, ultimately, earning potential. To support his opinion, Grose cites several studies which have shown that first-borns and only children usually reach higher educational goals, obtain greater status, and have greater financial success.<br><i>(Adapted from: Aim High 5)</i>", "cauHoi": [{"question": "Which of the following is the best title for the passage?", "choices": ["The Impact of Birth Order on Personality Traits and Career Choices", "The Challenges Faced by Middle Children in Diverse Families", "Parental Influence on the Development of Leadership Qualities", "Understanding the Unique Advantages of Being the Youngest Child"], "correctIndex": 0, "explain": "<b>Câu 53 chọn A</b><br><b>Giải thích:</b> Nội dung bài đọc bao quát cả hai khía cạnh: Ảnh hưởng của thứ tự sinh đối với tính cách (đoạn 2, 3, 4) và Sự nghiệp (đoạn 5)."}, {"question": "The word &quot;<b><u>keep tabs on</u></b>&quot; in paragraph 1 could be best replaced by", "choices": ["supervise", "neglect", "praise", "criticize."], "correctIndex": 0, "explain": "<b>Câu 54 chọn A</b><br><b>Giải thích:</b> Cụm từ &quot;keep tabs on&quot; mang nghĩa là theo dõi, để mắt tới, giám sát. Đồng nghĩa với &quot;supervise&quot;."}, {"question": "According to the passage, how does Ben Dattner explain the impact of birth order on personality development?", "choices": ["First-born children are more likely to be passive because of their parents&#x27; strict upbringing", "Second-born children develop stronger leadership skills due to being overshadowed by older siblings", "The upbringing of first-born children tends to make them more responsible and extroverted", "The youngest child&#x27;s creativity results from the strict rules imposed by their parents."], "correctIndex": 2, "explain": "<b>Câu 55 chọn C</b><br><b>Giải thích:</b> Dựa vào đoạn 2: &quot;the stricter upbringing of first-born children leads to them being more extroverted and confident. They also tend to be more responsible...&quot;."}, {"question": "The word &quot;<b><u>them</u></b>&quot; in paragraph 2 refers to", "choices": ["adaptation patterns", "different personalities", "parents", "first-born children."], "correctIndex": 3, "explain": "<b>Câu 56 chọn D</b><br><b>Giải thích:</b> Từ &quot;them&quot; trong câu &quot;their parents rely on them to help with the younger children&quot; thay thế cho danh từ &quot;first-born children&quot; (con cả) được nhắc đến ở ngay câu trước đó."}, {"question": "According to the third paragraph, which of the following statements is TRUE about middle children?", "choices": ["They are incapable of exhibiting leadership qualities due to the lack of responsibilities in their upbringing.", "They are typically quieter and prefer observation over participation in family dramas.", "They tend to display introverted behavior compared to their siblings.", "They are content with feeling unnoticed in the family and enjoy freedom compared to other siblings."], "correctIndex": 1, "explain": "<b>Câu 57 chọn B</b><br><b>Giải thích:</b> Dựa vào đoạn 3: &quot;Many second-born children are quiet, and they prefer to observe instead of participate in family dramas.&quot;"}, {"question": "In the passage, the author suggests that middle children may feel overlooked. Which of the following best explains why this is the case?", "choices": ["Middle children are often given more responsibility than both the oldest and youngest siblings", "Middle children are usually more independent and self-reliant due to their position in the family", "Middle children are frequently overshadowed by the birth order of their older and younger siblings", "Middle children are typically given the least freedom to explore creative outlets."], "correctIndex": 2, "explain": "<b>Câu 58 chọn C</b><br><b>Giải thích:</b> Dựa vào đoạn 3: Con thứ thường cảm thấy bị ngó lơ (overlooked) đặc biệt là khi &quot;another child is born before they are two years old&quot; (bị lu mờ bởi sự xuất hiện của anh chị em khác)."}, {"question": "What can be inferred about the impact of birth order on career outcomes?", "choices": ["First-borns are more likely to experience high levels of stress due to their role as leaders in the family.", "Middle children often struggle with career stability due to their tendency to avoid confrontation and decision-making.", "Youngest children are more adaptable in the workplace due to their exposure to less rigid parental expectations.", "The influence of birth order on career success is primarily dependent on the socioeconomic status of the family."], "correctIndex": 2, "explain": "<b>Câu 59 chọn C</b><br><b>Giải thích:</b> (Câu hỏi suy luận) Đoạn 4 chỉ ra rằng con út có thái độ thoải mái hơn (relaxed attitude), được tự do trải nghiệm (freedom to experiment) và ít luật lệ hơn (fewer restrictions). Điều này suy luận logic ra việc họ dễ thích nghi (adaptable) hơn ở nơi làm việc nhờ không bị gò bó bởi những kỳ vọng quá khắt khe."}, {"question": "In the context of the passage, what role does family structure play in shaping career success according to the experts?", "choices": ["Family structure plays no significant role in career outcomes, as these are determined by external factors.", "Family dynamics, such as the responsibilities and roles assigned within the family, shape personality traits that influence career choices and success.", "The family structure only affects social skills, which have little to no impact on career success.", "Career success is entirely dependent on external factors like education, with no impact from family upbringing."], "correctIndex": 1, "explain": "<b>Câu 60 chọn B</b><br><b>Giải thích:</b> Dựa vào tổng thể bài đọc (đặc biệt đoạn 2 và đoạn cuối). Các chuyên gia (Ben Dattner và Michael Grose) đều đồng tình rằng cấu trúc gia đình giao phó các vai trò (roles), trải nghiệm và trách nhiệm khác nhau; từ đó định hình các nét tính cách (personality traits) và tác động trực tiếp đến thành công nghề nghiệp (career choices and success)."}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Ascorbic acid (hay còn gọi là vitamin C), là hợp chất hữu cơ có công thức phân tử là <img class=\"anh-de\" src=\"data/anh/l17/bad9ced5b6e65f62.png\" alt=\"\" style=\"width:55px;height:24px;vertical-align:middle\">. Vitamin C được sử dụng để ngăn ngừa hoặc điều trị tình trạng thiếu vitamin C ở những người không nhận đủ vitamin từ chế độ ăn uống hàng ngày. Đặc tính chung của vitamin C là dễ bị oxi hóa, tan tốt trong nước, ít tan trong rượu và dung môi hữu cơ. Vitamin C có nhiều trong các loại rau, quả tươi.<br>Để xác định hàm lượng vitamin C có thể sử dụng phương pháp chuẩn độ acid – base. Chuẩn độ là phương pháp dùng để xác định nồng độ của các chất bằng cách thêm vào từ từ một lượng chất chuẩn đã biết nồng độ chính xác đến khi phản ứng xảy vừa đủ. Nguyên tắc của phương pháp chuẩn độ này như sau: Vitamin C được xác định trực tiếp bằng cách chuẩn độ với dung dịch NaOH, sử dụng chỉ thị là phenolphthalein theo phản ứng chuẩn độ:<br>Dung dịch tạo thành sau phản ứng là sodium ascorbate (<img class=\"anh-de\" src=\"data/anh/l17/50c63b9cdfe49ce0.png\" alt=\"\" style=\"width:76px;height:24px;vertical-align:middle\">) có môi trường base yếu nên khi có mặt chỉ thị phenolphthalein, dung dịch sẽ chuyển sang màu hồng.<br>Do đó, dừng chuẩn độ khi dung dịch chuyển từ không màu sang màu hồng nhạt. Phương pháp này thường dùng để chuẩn độ các dung dịch không màu hoặc màu rất nhạt để không ảnh hưởng đến màu hồng nhạt khi dừng chuẩn độ.", "cauHoi": [{"question": "Hãy chọn phát biểu <b>sai</b>.", "choices": ["Khối lượng vitamin C hoà tan trong 100 gam nước thấp hơn trong 100 gam rượu.", "Nước ép hoa quả giúp tăng hệ miễn dịch cho cơ thể và chống lão hóa.", "Số nguyên tử carbon và oxygen trong phân tử vitamin C là bằng nhau.", "Tại điểm tương đương, dung dịch chuyển từ không màu sang màu hồng nhạt."], "correctIndex": 0, "explain": "<b>Câu 103: Đáp án A</b><br><b>Phát biểu A sai:</b> Dựa vào thông tin trực tiếp từ văn bản: <i>&quot;Đặc tính chung của vitamin C là... tan tốt trong nước, ít tan trong rượu&quot;</i>. Điều này có nghĩa là khối lượng vitamin C hòa tan trong 100 gam nước phải <b>cao hơn</b> (lớn hơn) rất nhiều so với trong 100 gam rượu.<br><b>B:</b> Đúng theo kiến thức thực tế và sinh học cơ bản (vitamin C tăng đề kháng, chống oxi hóa).<br><b>C:</b> Đúng vì công thức phân tử của vitamin C là <img class=\"anh-de\" src=\"data/anh/l17/c6648f4a2a1b6815.png\" alt=\"\" style=\"width:55px;height:24px;vertical-align:middle\">, có 6 nguyên tử Carbon và 6 nguyên tử Oxygen (số lượng bằng nhau).<br><b>D:</b> Đúng theo dữ kiện đề bài: <i>&quot;dừng chuẩn độ khi dung dịch chuyển từ không màu sang màu hồng nhạt&quot;</i>."}, {"question": "Để xác định hàm lượng của ascorbic acid trong nước chanh, tiến hành chuẩn độ 100 mL dung dịch nước chanh thì hết 10,05 mL dung dịch NaOH 0,02 M. Nồng độ mol của ascorbic acid trong nước chanh là", "choices": ["<img class=\"anh-de\" src=\"data/anh/l17/350854f52a08f273.png\" alt=\"\" style=\"width:72px;height:24px;vertical-align:middle\"> M.", "0,020 M.", "<img class=\"anh-de\" src=\"data/anh/l17/902dcded8596bd00.png\" alt=\"\" style=\"width:72px;height:24px;vertical-align:middle\"> M.", "<img class=\"anh-de\" src=\"data/anh/l17/848ae5e86fb1f3f0.png\" alt=\"\" style=\"width:72px;height:24px;vertical-align:middle\"> M."], "correctIndex": 0, "explain": "<b>Câu 104. Đáp án A</b><br><b>Giải thích:</b><br>Dựa vào phương trình phản ứng chuẩn độ trong bài: <img class=\"anh-de\" src=\"data/anh/l17/90b2c7ae58213069.png\" alt=\"\" style=\"width:251px;height:24px;vertical-align:middle\"><br>Ta thấy tỉ lệ phản ứng giữa Vitamin C (ascorbic acid) và <img class=\"anh-de\" src=\"data/anh/l17/aa446215d8d3947b.png\" alt=\"\" style=\"width:48px;height:19px;vertical-align:middle\"> là 1:1.<br><b>Bước 1:</b> Tính số mol <img class=\"anh-de\" src=\"data/anh/l17/01a7cfcc5e07a856.png\" alt=\"\" style=\"width:48px;height:19px;vertical-align:middle\"> đã dùng.<br>Thể tích dung dịch <img class=\"anh-de\" src=\"data/anh/l17/e0551c4da4a13f3a.png\" alt=\"\" style=\"width:48px;height:19px;vertical-align:middle\">: <img class=\"anh-de\" src=\"data/anh/l17/4a78b770e7d980fe.png\" alt=\"\" style=\"width:221px;height:26px;vertical-align:middle\"><br>Nồng độ <img class=\"anh-de\" src=\"data/anh/l17/a6529874453e8aba.png\" alt=\"\" style=\"width:48px;height:19px;vertical-align:middle\">: <img class=\"anh-de\" src=\"data/anh/l17/4efd52b96d20f4fa.png\" alt=\"\" style=\"width:90px;height:24px;vertical-align:middle\"><br>Số mol <img class=\"anh-de\" src=\"data/anh/l17/a6529874453e8aba.png\" alt=\"\" style=\"width:48px;height:19px;vertical-align:middle\">:<br><img class=\"anh-de\" src=\"data/anh/l17/4e2a01b5d6a14a21.png\" alt=\"\" style=\"width:282px;height:26px\"><br><b>Bước 2:</b> Tính nồng độ của ascorbic acid.<br>Vì tỉ lệ 1:1, suy ra số mol ascorbic acid có trong 100 mL nước chanh là:<br><img class=\"anh-de\" src=\"data/anh/l17/df71a2131c1aa85c.png\" alt=\"\" style=\"width:192px;height:26px;vertical-align:middle\"><br>Thể tích mẫu nước chanh: <img class=\"anh-de\" src=\"data/anh/l17/7c9e01b8a155416c.png\" alt=\"\" style=\"width:144px;height:24px;vertical-align:middle\"><br>Nồng độ mol của ascorbic acid là: <img class=\"anh-de\" src=\"data/anh/l17/e3971fbc49d18ff1.png\" alt=\"\" style=\"width:238px;height:47px;vertical-align:middle\">"}, {"question": "Tại sao chất chỉ thị phenolphthalein được sử dụng trong phương pháp chuẩn độ vitamin C bằng NaOH?", "choices": ["Vì dung dịch sau phản ứng có môi trường acid.", "Vì phenolphthalein không màu trong môi trường acid và chuyển sang màu hồng trong môi trường kiềm.", "Vì vitamin C có màu và phenolphthalein giúp dễ dàng quan sát sự thay đổi màu.", "Vì phenolphthalein phản ứng trực tiếp với vitamin C."], "correctIndex": 1, "explain": "<b>Câu 105: Đáp án B</b><br><b>Đáp án B đúng:</b> Đây là tính chất đặc trưng của chất chỉ thị phenolphthalein. Ban đầu, môi trường chứa vitamin C là môi trường acid nên dung dịch không màu. Khi nhỏ từ từ <img class=\"anh-de\" src=\"data/anh/l17/e30f6b939aa908bc.png\" alt=\"\" style=\"width:48px;height:19px;vertical-align:middle\"> đến điểm tương đương (phản ứng vừa đủ), dung dịch tạo thành là muối sodium ascorbate (<img class=\"anh-de\" src=\"data/anh/l17/5a63514d0f8932d2.png\" alt=\"\" style=\"width:76px;height:24px;vertical-align:middle\">).<br>Văn bản cũng đã giải thích rõ: <i>&quot;Dung dịch tạo thành sau phản ứng là sodium ascorbate... có môi trường base yếu&quot;</i>. Do môi trường chuyển sang kiềm (base), phenolphthalein ngay lập tức chuyển sang màu hồng, giúp người làm thí nghiệm nhận biết điểm dừng chuẩn độ.<br><b>Các đáp án khác sai vì:</b><br>A sai: Môi trường sau phản ứng là base yếu, không phải acid.<br>C sai: Phương pháp này áp dụng cho dung dịch không màu hoặc màu nhạt, bản thân vitamin C không có màu đậm để tự làm chỉ thị.<br>D sai: Chất chỉ thị đổi màu do sự thay đổi pH của môi trường (nồng độ <img class=\"anh-de\" src=\"data/anh/l17/1b10089349a9caf6.png\" alt=\"\" style=\"width:23px;height:20px;vertical-align:middle\"> hoặc <img class=\"anh-de\" src=\"data/anh/l17/70e5862932d29e20.png\" alt=\"\" style=\"width:34px;height:21px;vertical-align:middle\">), chứ không tham gia phản ứng trực tiếp với chất cần chuẩn độ."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br><img class=\"anh-de\" src=\"data/anh/l17/3d46b7272c99033b.png\" alt=\"\" style=\"width:319px;height:265px\">Một nhóm học sinh thực hiện dự án chưng cất tinh dầu bạc hà bằng phương pháp “lôi cuốn hơi nước” với hệ thống như hình bên. Qui trình thực hiện như sau: Nước trong bình (2) nhận nhiệt từ nguồn nhiệt (1), hóa hơi và đi qua nguyên liệu (3), cuốn theo tinh dầu bạc hà; Hỗn hợp hơi nước - tinh dầu (4) đi qua ống dẫn (5) vào bình ngưng (6) được làm nguội và ngưng tụ thành hỗn hợp lỏng và thu vào bình chứa (7); Sau đó dùng kĩ thuật tách để lấy tinh dầu khỏi nước.<b> </b>Nhóm sử dụng bình ngưng chứa 5,0 lít nước ban đầu ở 15,0 <sup>o</sup>C và không thay nước trong cả quá trình. Sau 4 giờ thì hoàn thành quá trình chưng cất, khi đó nước trong<b> </b>bình ngưng có nhiệt độ 40,0<b><sup> </sup></b><sup>o</sup>C.<b> </b>Bỏ qua sự tỏa nhiệt của bình ngưng ra môi trường, khối lượng riêng và nhiệt dung riêng của nước là<b> </b><img class=\"anh-de\" src=\"data/anh/l17/8b252b40a0b15e49.png\" alt=\"\" style=\"width:128px;height:25px;vertical-align:middle\"><img class=\"anh-de\" src=\"data/anh/l17/f886a409586e3caf.png\" alt=\"\" style=\"width:104px;height:45px;vertical-align:middle\">", "cauHoi": [{"question": "Dựa vào bài đọc, trong quá trình chưng cất lôi cuốn hơi nước, chức năng chính của bình ngưng là gì?", "choices": ["Đun sôi nước để tạo ra áp suất đẩy hơi nước đi qua nguyên liệu.", "Chứa nguyên liệu thực vật để hơi nước đi qua và cuốn theo tinh dầu.", "Tách tinh dầu nguyên chất ra khỏi nước dựa vào sự chênh lệch khối lượng riêng.", "Làm lạnh để ngưng tụ hỗn hợp hơi (nước và tinh dầu) chuyển sang trạng thái lỏng."], "correctIndex": 3, "explain": "<b>Câu 106: Chọn D</b><br><b>Giải thích:</b> Câu hỏi bám sát vào chi tiết trong đoạn văn 2: <i>&quot;Hỗn hợp hơi... được dẫn qua một hệ thống bình ngưng... hạ nhiệt độ và ngưng tụ thành hỗn hợp lỏng&quot;</i>. Các đáp án khác sai chức năng (A là bình đun, B là buồng nguyên liệu, C là bình chiết)."}, {"question": "Dựa vào nguyên lí nhiệt động lực học trong hệ thống, phát biểu nào sau đây là đúng khi nói về sự trao đổi nhiệt bên trong bình ngưng?", "choices": ["Hỗn hợp hơi đã nhận nhiệt từ nước làm mát để chuyển từ thể khí sang thể lỏng.", "Hỗn hợp hơi tỏa nhiệt cho nước làm mát, làm động năng phân tử của nước làm mát tăng lên.", "Tốc độ truyền nhiệt giữa hỗn hợp hơi và nước làm mát sẽ tăng dần khi nhiệt độ nước làm mát tăng từ <img class=\"anh-de\" src=\"data/anh/l17/727b5a8561017d5e.png\" alt=\"\" style=\"width:49px;height:24px;vertical-align:middle\"> lên <img class=\"anh-de\" src=\"data/anh/l17/ce7851128acfe53e.png\" alt=\"\" style=\"width:50px;height:24px;vertical-align:middle\">.", "Nhiệt độ của hỗn hợp lỏng (nước và tinh dầu) thu được sau khi qua bình ngưng luôn bằng đúng nhiệt độ của nước làm mát."], "correctIndex": 1, "explain": "<b>Câu 107: Chọn B</b><br><b>Giải thích:</b> * A sai vì quá trình ngưng tụ (từ khí sang lỏng) là quá trình <b>tỏa nhiệt</b>, hơi phải tỏa nhiệt cho nước chứ không phải nhận nhiệt.<br>B đúng vì hỗn hợp hơi tỏa nhiệt cho nước làm mát, khiến nhiệt độ nước làm mát tăng (từ 15 lên 40 độ), đồng nghĩa với động năng trung bình của các phân tử nước làm mát tăng.<br>C sai vì khi nhiệt độ nước làm mát tăng lên, độ chênh lệch nhiệt độ (<img class=\"anh-de\" src=\"data/anh/l17/c89ff2aecbdc1e57.png\" alt=\"\" style=\"width:26px;height:17px;vertical-align:middle\">) giữa hỗn hợp hơi nóng và nước làm mát giảm đi, dẫn đến tốc độ trao đổi nhiệt sẽ <b>giảm dần</b>."}, {"question": "Trong thực tế, để đảm bảo hiệu suất ngưng tụ tốt nhất, nhiệt độ nước trong bình ngưng không được phép vượt quá <img class=\"anh-de\" src=\"data/anh/l17/4bda48eeb63134fa.png\" alt=\"\" style=\"width:50px;height:24px;vertical-align:middle\">. Giả sử tốc độ truyền nhiệt lượng từ hỗn hợp hơi sang nước làm mát là ổn định trong suốt quá trình chưng cất. Nhóm học sinh cần thay nước làm mát mới (có nhiệt độ <img class=\"anh-de\" src=\"data/anh/l17/2d7afaf433fb39ea.png\" alt=\"\" style=\"width:49px;height:24px;vertical-align:middle\">) sau mỗi khoảng thời gian là bao lâu để đáp ứng yêu cầu trên?", "choices": ["1 giờ", "1,6 giờ", "2 giờ", "2,5 giờ"], "correctIndex": 1, "explain": "<b>Giải thích </b>Độ tăng nhiệt độ trong 4 giờ là: <img class=\"anh-de\" src=\"data/anh/l17/0e0db6e41c9dc44c.png\" alt=\"\" style=\"width:216px;height:26px;vertical-align:middle\">.<br>Tốc độ tăng nhiệt độ của nước là: <img class=\"anh-de\" src=\"data/anh/l17/a16bc0377cda1432.png\" alt=\"\" style=\"width:158px;height:24px;vertical-align:middle\">.<br>Để nhiệt độ nước không vượt quá <img class=\"anh-de\" src=\"data/anh/l17/c7013c204fb0732a.png\" alt=\"\" style=\"width:50px;height:24px;vertical-align:middle\">, độ tăng nhiệt độ tối đa cho phép là: <img class=\"anh-de\" src=\"data/anh/l17/c687bf523594999a.png\" alt=\"\" style=\"width:220px;height:26px;vertical-align:middle\">.<br>Thời gian tối đa để nước đạt đến giới hạn này là: <img class=\"anh-de\" src=\"data/anh/l17/80a4f55ac7903f06.png\" alt=\"\" style=\"width:137px;height:47px;vertical-align:middle\">.<br>Vậy cứ sau 1,6h học sinh cần thay nước một lần."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br>Trong việc đẩy lùi đại dịch Covid-19 do virus đường hô hấp SARS – CoV – 2 gây ra trên khắp thế giới (giai đoạn 2019 – 2022), các vaccine của Pfizer/BioNTech và Moderna là những vaccine RNA đầu tiên được cấp phép sử dụng. Không giống vaccine truyền thống, vaccine RNA mang trình tự mRNA (đã được biến đổi hóa học một số nucleotide nhằm làm tăng tính bền của RNA) mã hóa cho các kháng nguyên đặc trưng của virus gây bệnh được đưa thẳng vào cơ thể. Chính các tế bào của cơ thể trở thành “nhà máy sản xuất protein kháng nguyên của virus” và hoạt hóa hệ miễn dịch chống lại virus gây bệnh. Các bằng chứng tới nay cho thấy, vaccine RNA được chế tạo nhanh hơn, giá thành rẻ hơn so với các vaccine truyền thống. Đây là một thành tựu mới của công nghệ gene.<br><i>(Tr28, Chuyên đề học tập Sinh học 12 – KNTT)</i>", "cauHoi": [{"question": "Các vaccine có công nghệ RNA mới hoạt động theo cách thức nào sau đây?", "choices": ["Tiêm trực tiếp virus sống vào cơ thể.", "Tiêm vật chất di truyền của virus vào cơ thể.", "Tiêm tế bào virus đã chết vào cơ thể.", "Tiêm protein của virus vào cơ thể."], "correctIndex": 1, "explain": "<b>Câu 109: Đáp án B</b><br>Đề bài nêu rõ &quot;vaccine RNA mang trình tự mRNA... được đưa thẳng vào cơ thể&quot;. Trong sinh học, mRNA (RNA thông tin) chính là một dạng <b>vật chất di truyền</b>.<br>Công nghệ này không tiêm trực tiếp virus (sống hoặc chết) như vaccine truyền thống (loại A và C), cũng không tiêm trực tiếp protein của virus (loại D). Nó chỉ đưa &quot;bản thiết kế&quot; (mRNA) vào, để chính tế bào cơ thể chúng ta tự tổng hợp ra protein đó."}, {"question": "Vì sao các vaccine RNA có thể được chế tạo nhanh hơn so với các vaccine truyền thống?", "choices": ["Vaccine RNA có thể sản xuất mà không cần phải nuôi cấy virus.", "Vaccine RNA sử dụng virus chết để kích hoạt miễn dịch.", "Vaccine RNA có thể thay thế các kháng thể để tạo ra miễn dịch.", "Vaccine RNA không cần phải tiêm nhiều lần."], "correctIndex": 0, "explain": "<b>Câu 110: Đáp án A</b><br>Để sản xuất các loại vaccine truyền thống (vaccine bất hoạt, vaccine giảm độc lực), các nhà khoa học bắt buộc phải trải qua bước <b>nuôi cấy virus</b> trong phòng thí nghiệm (ví dụ nuôi cấy trên trứng gà ấp hoặc tế bào động vật). Quá trình này tốn rất nhiều thời gian và đòi hỏi điều kiện an toàn sinh học ngặt nghèo.<br>Trong khi đó, vaccine mRNA chỉ cần biết được trình tự gen của virus là có thể tổng hợp nhân tạo hàng loạt đoạn mRNA trong phòng thí nghiệm bằng các phản ứng sinh hóa mà <b>không cần phải nuôi cấy virus sống</b>. Điều này giúp rút ngắn tối đa thời gian chế tạo."}, {"question": "Tại sao mRNA trong vaccine không thể gây ra bệnh cho người tiêm?", "choices": ["mRNA không mã hóa cho toàn bộ virus mà chỉ mã hóa một phần nhỏ.", "mRNA không đủ mạnh để kích hoạt hệ miễn dịch.", "mRNA được vô hiệu hóa hoàn toàn trong cơ thể.", "mRNA không tồn tại lâu trong cơ thể người sau khi tiêm."], "correctIndex": 0, "explain": "<b>Câu 111 Đáp án A</b><br><b>Giải thích:</b> Dữ kiện trong đoạn văn ghi rõ: mRNA trong vaccine chỉ &quot;mã hóa cho các kháng nguyên đặc trưng của virus&quot; (ví dụ như protein gai ở lớp vỏ của SARS-CoV-2).<br>Vì nó chỉ mang thông tin của một <b>phần rất nhỏ</b> (một loại protein) chứ không chứa toàn bộ bộ gen (bản đồ di truyền hoàn chỉnh) của virus, nên nó tuyệt đối không thể tự lắp ráp thành một hạt virus hoàn chỉnh trong cơ thể để gây ra bệnh lý. Do đó, người tiêm hoàn toàn an toàn trước nguy cơ nhiễm bệnh từ chính vaccine."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>Các hoạt động khai thác tài nguyên nước thượng nguồn, biến đổi khí hậu và nước biển dâng đã và đang gây ra những tác động tiêu cực đến Đồng bằng sông Cửu Long trong đó xâm nhập mặn được xem là một trong những tác động nghiêm trọng nhất. Trong khi các nghiên cứu trước đây thường tập trung đánh giá tác động riêng lẻ của các hoạt động phát triển thượng nguồn hoặc nước biển dâng đến xâm nhập mặn, nghiên cứu này trình bày kết quả đánh giá diễn biến xâm nhập mặn vùng đồng bằng sông Cửu Long đồng thời theo kịch bản hiện trạng và các kịch bản phát triển kinh tế - xã hội thượng nguồn đến năm 2030 và 2050 sử dụng phương pháp mô hình toán và GIS. Kết quả tính toán cho thấy so với kịch bản hiện trạng, đến năm 2050 chiều dài xâm nhập mặn lớn nhất tương ứng với ranh mặn 4 g/l sẽ tăng 5,6 km trên sông Tiền, 6,2 km trên sông Hậu và 13,7 km trên sông Cổ Chiên. Dự báo đến năm 2050 khoảng hơn 2,5 triệu ha đất vùng Đồng bằng sông Cửu Long sẽ bị nhiễm mặn với độ mặn lớn hơn 1 g/l, tăng 9,1% so với kịch bản hiện trạng. Các kết quả tính toán của nghiên cứu này sẽ cung cấp thông tin quan trọng phục vụ đề xuất các giải pháp thích ứng, giảm thiểu tác động của hoạt động khai thác tài nguyên nước thượng nguồn, biến đổi khí hậu và nước biển dâng đến xâm nhập mặn vùng đồng bằng sông Cửu Long. (Nguồn: Tạp chí khí tượng thủy văn)", "cauHoi": [{"question": "Xâm nhập mặn ở Đồng bằng sông Cửu Long xảy ra <b>không</b> phải do tác động từ tình trạng nào sau đây?", "choices": ["Sạt lở đất vùng ven các con sông lớn.", "Khai thác tài nguyên nước thượng nguồn.", "Biến đổi khí hậu.", "Nước biển dâng."], "correctIndex": 0, "explain": "<b>Câu 112: Đáp án A</b><br><b>Giải thích:</b> Ngay ở câu đầu tiên của đoạn trích, tác giả đã chỉ rõ các nguyên nhân gây ra tác động tiêu cực (bao gồm xâm nhập mặn) là: &quot;Các hoạt động khai thác tài nguyên nước thượng nguồn, biến đổi khí hậu và nước biển dâng&quot;. Sạt lở đất không được nhắc đến như một nguyên nhân gây xâm nhập mặn trong văn bản này."}, {"question": "Mục đích của nghiên cứu về xâm nhập mặn vùng Đồng bằng sông Cửu Long là gì?", "choices": ["Đề xuất giải pháp thích ứng và giảm thiểu tác động xâm nhập mặn.", "Có kế hoạch khai thác hiệu quả tài nguyên nước ở thượng nguồn.", "Dự đoán diện tích đất canh tác sẽ mất đi do tác động xâm nhập mặn.", "Giải quyết triệt để tình trạng biến đổi khí hậu và nước biển dâng."], "correctIndex": 0, "explain": "<b>Câu 113: Đáp án A</b><br><b>Giải thích:</b> Thông tin này nằm ở câu cuối cùng của đoạn trích: &quot;Các kết quả tính toán của nghiên cứu này sẽ cung cấp thông tin quan trọng phục vụ <b>đề xuất các giải pháp thích ứng, giảm thiểu tác động</b> của hoạt động khai thác tài nguyên nước thượng nguồn, biến đổi khí hậu và nước biển dâng đến xâm nhập mặn vùng đồng bằng sông Cửu Long.&quot;"}, {"question": "Theo đoạn thông tin, diện tích bị nhiễm mặn với độ mặn lớn hơn 1 g/l của Đồng bằng sông Cửu Long theo kịch bản hiện trạng là (làm tròn đến hàng phần trăm của đơn vị triệu ha)", "choices": ["2,27 triệu ha.", "2,00 triệu ha.", "2,72 triệu ha.", "2,29 triệu ha."], "correctIndex": 3, "explain": "<b>Câu 114: Đáp án D</b><br>Văn bản cung cấp dữ kiện: &quot;Dự báo đến năm 2050 khoảng hơn 2,5 triệu ha đất... sẽ bị nhiễm mặn... tăng 9,1% so với kịch bản hiện trạng&quot;.<br>Gọi <img class=\"anh-de\" src=\"data/anh/l17/dac6da5d0420d9e5.png\" alt=\"\" style=\"width:13px;height:14px;vertical-align:middle\"> (triệu ha) là diện tích bị nhiễm mặn theo kịch bản hiện trạng.<br>Ta có phương trình: <img class=\"anh-de\" src=\"data/anh/l17/37161684dcdc29c9.png\" alt=\"\" style=\"width:106px;height:21px;vertical-align:middle\"><br>Suy ra: <img class=\"anh-de\" src=\"data/anh/l17/eed3c6a0b5c77857.png\" alt=\"\" style=\"width:248px;height:44px;vertical-align:middle\"> (triệu ha)<br>Làm tròn đến hàng phần trăm (2 chữ số thập phân), ta được kết quả là <b>2,29 triệu ha</b>. Chữ số ở hàng phần nghìn là 1 (&lt; 5) nên giữ nguyên chữ số hàng phần trăm. Do đó, đáp án D là chính xác."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117 </b><br>Ở Đông Nam Á, đầu những năm 30, một số Đảng Cộng sản được thành lập, mở ra một thời kì mới trong cuộc đấu tranh giải phóng dân tộc. Riêng ở Việt Nam, cuộc khởi nghĩa Yên Bái tháng 2-1930 (do Việt Nam Quốc dân đảng tổ chức) bị thất bại đã chấm dứt vai trò lãnh đạo cách mạng của giai cấp tư sản dân tộc, đồng thời cao trào cách mạng giải phóng dân tộc 1930 - 1931, mà đỉnh cao là phong trào Xô viết Nghệ -Tĩnh, đã mở ra thời kì cách mạng Việt Nam đi theo sự lãnh đạo của giai cấp công nhân và chính Đảng mácxít - lêninnít của nó - Đảng Cộng sản Đông Dương. Ở Philíppin, cuộc khởi nghĩa nông dân chống ách bóc lột của địa chủ phong kiến gắn liền với cuộc đấu tranh chống đế quốc bùng nổ năm 1931 đã buộc Mĩ phải trao trả quyền tự trị cho nước này. Ở Miến Điện, phong trào khởi nghĩa nông dân được diễn ra từ cuối năm 1930 đến mùa xuân năm 1932. Đầu năm 1933, ở Inđônêxia đã bùng nổ cuộc khởi nghĩa của thủy binh trên tàu chiến Đơ Giơven Pơrôvinxien.<br>(Nguồn: https://tulieuvankien.dangcongsan.vn/)", "cauHoi": [{"question": "Trong giai đoạn đầu những năm 1930, phong trào đấu tranh giải phóng dân tộc ở Đông Nam Á có đặc điểm gì nổi bật?", "choices": ["Chỉ diễn ra dưới hình thức khởi nghĩa vũ trang do giai cấp tư sản lãnh đạo.", "Gắn liền với sự ra đời và lãnh đạo của các Đảng Cộng sản.", "Chỉ tập trung vào đấu tranh chống phong kiến, chưa chống thực dân.", "Tập trung ở Đông Nam Á hải đảo, phong trào ở Đông Nam Á lục địa tạm lắng xuống."], "correctIndex": 1, "explain": "<b>Câu 115: Đáp án B</b><br><b>Giải thích:</b> Ngay câu mở đầu của đoạn trích đã khẳng định đặc điểm nổi bật nhất của giai đoạn này: <i>&quot;Ở Đông Nam Á, đầu những năm 30, một số Đảng Cộng sản được thành lập, mở ra một thời kì mới trong cuộc đấu tranh giải phóng dân tộc.&quot;</i>"}, {"question": "Lần đầu tiên giai cấp công nhân Việt Nam cùng với chính đảng của mình thể hiện vai trò lãnh đạo thông qua sự kiện nào?", "choices": ["Cao trào cách mạng giải phóng dân tộc 1930 - 1931.", "Cuộc khởi nghĩa Yên Bái tháng 2 - 1930.", "Sự thành lập Đảng Cộng sản Đông Dương.", "Khởi nghĩa nông dân cuối năm 1930 đến mùa xuân năm 1932."], "correctIndex": 0, "explain": "<b>Câu 116: Đáp án A</b><br><b>Giải thích:</b> Đoạn trích nêu rõ sự thất bại của khởi nghĩa Yên Bái đã chấm dứt vai trò lãnh đạo của giai cấp tư sản, đồng thời <i>&quot;cao trào cách mạng giải phóng dân tộc 1930 - 1931... đã mở ra thời kì cách mạng Việt Nam đi theo sự lãnh đạo của giai cấp công nhân và chính Đảng mácxít - lêninnít của nó&quot;</i>. Đây là bước tập dượt và là lần đầu tiên giai cấp công nhân thể hiện vai trò lãnh đạo thực tế qua một phong trào quần chúng rộng lớn."}, {"question": "Nội dung nào sau đây phản ánh điểm tương đồng giữa các phong trào đấu tranh giải phóng dân tộc ở Việt Nam, Philíppin, Miến Điện và Inđônêxia đầu những năm 1930?", "choices": ["Do giai cấp tư sản dân tộc lãnh đạo.", "Kết quả giành được độc lập hoàn toàn.", "Lực lượng chính là giai cấp công nhân.", "Hình thức chủ yếu là khởi nghĩa vũ trang."], "correctIndex": 3, "explain": "<b>Câu 117: Đáp án D</b><br><b>Giải thích:</b> Xuyên suốt đoạn trích, phương pháp đấu tranh ở tất cả các quốc gia được nhắc đến đều mang hình thức bạo lực/vũ trang: cuộc <b>khởi nghĩa</b> Yên Bái và phong trào Xô viết (Việt Nam), <b>khởi nghĩa</b> nông dân (Philíppin, Miến Điện), và cuộc <b>khởi nghĩa</b> của thủy binh (Inđônêxia). Các đáp án A, B, C đều không đúng với bối cảnh hoặc lực lượng của tất cả các nước này."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>Theo ông Nguyễn Hoàng Thanh Chương, Giám đốc dịch vụ tuyển dụng toàn quốc, Adecco Việt Nam, Gig work (công việc tự do hoặc việc làm thời vụ) phát triển mạnh mẽ trong thời đại công nghệ số và sự bùng nổ của nền kinh tế đã xuất hiện những công việc mới. Điều đó hình thành những vị trí việc làm tạm thời, bán thời gian, còn các công ty có xu hướng thuê lao động tự do thay vì nhân viên toàn thời gian.<br>Công việc thời vụ có một số ưu thế vượt trội so với những công việc truyền thống như thời gian làm việc linh hoạt, khối lượng công việc tùy ý theo khả năng cho phép. Những yếu tố này chính là điều kiện tiên quyết để người lao động có thể cân bằng được cuộc sống và là điểm thu hút ngày càng nhiều người trẻ tham gia nhóm việc làm này. <i>(Nguồn: Báo Người Lao động)</i>", "cauHoi": [{"question": "Đặc điểm cơ bản nào của Gig work là yếu tố trực tiếp thu hút nhóm người trẻ tham gia?", "choices": ["Khả năng giúp người lao động cân bằng được cuộc sống cá nhân.", "Sự xuất hiện đa dạng của các vị trí việc làm tạm thời, bán thời gian.", "Nhu cầu tuyển dụng lao động tự do ngày càng cao từ các công ty.", "Thời gian làm việc linh hoạt, khối lượng công việc tùy ý theo khả năng."], "correctIndex": 3, "explain": "<b>Câu 118 Chọn D.</b> Đoạn 2 nêu rõ thời gian linh hoạt, khối lượng tùy ý là ưu thế vượt trội và là điều kiện tiên quyết (đặc điểm trực tiếp). Đáp án A là hệ quả của đặc điểm này."}, {"question": "Theo đoạn thông tin, xu hướng chuyển dịch nhân sự của các công ty trong thời đại số là gì?", "choices": ["Ưu tiên các vị trí bán thời gian kết hợp với nhân sự toàn thời gian.", "Gia tăng các hợp đồng thời vụ nhằm giảm thiểu chi phí nhân sự.", "Thuê lao động tự do thay thế dần cho đội ngũ nhân viên toàn thời gian.", "Cung cấp các công việc có thời gian linh hoạt để thu hút giới trẻ."], "correctIndex": 2, "explain": "<b>Câu 119 Chọn C</b> Đoạn 1 khẳng định &quot;...còn các công ty có xu hướng thuê lao động tự do thay vì nhân viên toàn thời gian&quot;. Đáp án B có vẻ hợp lý với thực tế nhưng không có dữ kiện trong bài (không nhắc đến &quot;giảm thiểu chi phí&quot;)."}, {"question": "Trong bối cảnh như đã nêu, để được hưởng đầy đủ những quyền lợi của người lao động theo pháp luật Việt Nam, bạn nên làm gì?", "choices": ["Làm công việc thời vụ và tham gia đóng bảo hiểm xã hội tự nguyện.", "Kí hợp đồng lao động chính thức với một cơ quan, doanh nghiệp.", "Trở thành đối tác của một công ty đa quốc gia và tham gia bảo hiểm nhân thọ.", "Thành lập doanh nghiệp tư nhân và trở thành người sử dụng lao động."], "correctIndex": 1, "explain": "<b>Câu 119 Chọn B</b> Từ khóa quan trọng nhất của câu hỏi là <b>&quot;hưởng ĐẦY ĐỦ những quyền lợi&quot;</b>. Theo Luật Lao động Việt Nam, chỉ khi có <b>Hợp đồng lao động chính thức</b>, người lao động mới được pháp luật bảo vệ trọn vẹn các chế độ: Bảo hiểm xã hội bắt buộc, Bảo hiểm y tế, Bảo hiểm thất nghiệp, thai sản, ốm đau, nghỉ phép...<br><i>Các đáp án khác sai vì:</i><br><b>A:</b> BHXH tự nguyện không có chế độ thai sản, ốm đau hay bảo hiểm thất nghiệp.<br><b>C:</b> Bảo hiểm nhân thọ là dịch vụ thương mại, không phải quyền lợi an sinh xã hội theo Luật Lao động.<br><b>D:</b> Mở doanh nghiệp nghĩa là em đã trở thành &quot;người sử dụng lao động&quot; (làm chủ), không còn là đối tượng &quot;người lao động&quot; mà câu hỏi hướng tới."}], "khongXaoTron": true}]};
